#!/usr/bin/env node
"use strict";
// Cyrus Test Flight (R0): boot ONE disposable real Paper server for one Minecraft version, run the checks, tear it
// down, and print a JSON report. Runs on the build host (node-2) as root, under TF_ROOT only.
//
//   node runner.js run <resolved-spec.json>      -> report JSON on stdout (exit 0), busy (75), bad spec (2)
//   node runner.js setup <javaRelease>           -> fetch + verify one pinned JDK (21 or 25), print its path
//
// Safety model (node-2 is a shared build host):
// - one Test Flight at a time: `flock -n` on TF_ROOT/testflight.lock (a second run gets status "busy" at once);
// - the server runs inside a private network namespace (loopback only: no internet, no host ports) as uid/gid 65534
//   with no_new_privs, nice 10, -Xmx<=1g, 2 visible CPUs, an RSS watchdog and a hard wall-clock timeout;
// - processes are only ever killed by exact PID (the java PID we spawned, or a PID whose cmdline carries this run's
//   unique -Dnxeon.testflight.run marker). Never by pattern;
// - the run dir is removed afterwards; downloads (JDKs, Paper jars) are verified by sha256 before use.
// Every check is pass / fail / not_run with evidence. A check never passes unless it ran.

const fs = require("fs");
const path = require("path");
const net = require("net");
const os = require("os");
const crypto = require("crypto");
const { spawn, spawnSync } = require("child_process");
const L = require("./lib.js");

const RUNNER_VERSION = "tf-lite-1";
const TF_ROOT = process.env.TF_ROOT || "/tank/nxeon-build/tmp/testflight";
const LOCK = path.join(TF_ROOT, "testflight.lock");
const RUN_UID = 65534;
const BUSY_EXIT = 75;

// Pinned toolchains (Adoptium API checksums, verified 2026-10-10). Bump deliberately, never float.
const JDKS = {
  21: { release: "jdk-21.0.12.1+1", sha256: "ce79869e1307ed8ee1e2baa86a412b1eb5b75d10a01006d788a6f968bcfaee94",
    url: "https://github.com/adoptium/temurin21-binaries/releases/download/jdk-21.0.12.1%2B1/OpenJDK21U-jdk_x64_linux_hotspot_21.0.12.1_1.tar.gz" },
  25: { release: "jdk-25.0.4.1+1", sha256: "dbb698396d478e7fa2b1e50f4103324b2a99b90569ee27c33f2261f9215cf41e",
    url: "https://github.com/adoptium/temurin25-binaries/releases/download/jdk-25.0.4.1%2B1/OpenJDK25U-jdk_x64_linux_hotspot_25.0.4.1_1.tar.gz" },
};

const log = (...a) => process.stderr.write(`[testflight] ${a.join(" ")}\n`);
const sha256File = (f) => crypto.createHash("sha256").update(fs.readFileSync(f)).digest("hex");
const now = () => Date.now();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const clip = (s, n = 300) => String(s).slice(0, n);

// Test Flight spec validation + resolution against the version registry. Pure (no I/O): fails closed on anything
// the registry cannot vouch for (unknown version, no pinned Paper server jar).
import { getVersion, type VersionRow } from "../versions/registry";
import type { CheckId, ResolvedSpec, TestFlightSpec, LogMatcher, ServerFile } from "./types";
import { CHECK_IDS } from "./types";

export const TF_DEFAULT_ROOT = "/tank/nxeon-build/tmp/testflight";
export const DEFAULT_TIMEOUTS = { bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 } as const;
export const DEFAULT_MEMORY = { xmxMb: 1024, rssCapMb: 1800 } as const;
const RESERVED_COMMANDS = /^\/?(stop|restart|op|deop|reload)\b/i;
const SHA256 = /^[0-9a-f]{64}$/;
/** Same rule as lib.js SERVER_FILE_RE: relative, under plugins/, plain segments only. */
export const SERVER_FILE_RE = /^plugins\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}(\/[A-Za-z0-9_-][A-Za-z0-9_.-]{0,63}){0,3}$/;
export const MAX_SERVER_FILES = 16;
export const MAX_SERVER_FILE_BYTES = 64 * 1024;

function checkFile(f: ServerFile | undefined, key: string, errs: string[]) {
  if (!f || typeof f.path !== "string" || !SERVER_FILE_RE.test(f.path) || f.path.split("/").includes("..")) errs.push(`${key}.path must be a relative path under plugins/ (plain segments)`);
  if (!f || typeof f.content !== "string" || Buffer.byteLength(f.content, "utf8") > MAX_SERVER_FILE_BYTES) errs.push(`${key}.content must be text of at most ${MAX_SERVER_FILE_BYTES} bytes`);
}

function checkMatchers(list: LogMatcher[] | undefined, key: string, errs: string[]) {
  for (const [i, m] of (list ?? []).entries()) {
    if (!m || typeof m.pattern !== "string" || !m.pattern) { errs.push(`${key}[${i}]: pattern is required`); continue; }
    if (m.pattern.length > 400) errs.push(`${key}[${i}]: pattern longer than 400 chars`);
    try { new RegExp(m.pattern, (m.flags ?? "").replace(/[^imsu]/g, "")); } catch (e) { errs.push(`${key}[${i}]: ${(e as Error).message}`); }
  }
}

export type PinnedRow = VersionRow & { paperBuild: number; paperServerSha256: string };
export type SpecCheck = { ok: true; row: PinnedRow } | { ok: false; errors: string[] };

/** Validate a caller spec. `lookup` is injectable for tests; defaults to the real registry. */
export function validateSpec(spec: TestFlightSpec, lookup: (id: string) => VersionRow | null = getVersion): SpecCheck {
  const errs: string[] = [];
  const row = lookup(String(spec?.version ?? ""));
  if (!row) errs.push(`Minecraft ${spec?.version} is not in the version registry`);
  else {
    if (!row.paperBuild || !Number.isInteger(row.paperBuild)) errs.push(`${row.id} has no pinned Paper server build, so it cannot be test-flown`);
    if (!SHA256.test(String(row.paperServerSha256 ?? ""))) errs.push(`${row.id} has no pinned Paper server sha256`);
  }
  const arts = [...(spec.plugins ?? []).map((a, i) => ["plugins", i, a] as const), ...(spec.datapacks ?? []).map((a, i) => ["datapacks", i, a] as const)];
  for (const [k, i, a] of arts) {
    const hasLocal = typeof a?.localPath === "string" && a.localPath.length > 0;
    const hasRemote = typeof a?.remotePath === "string" && a.remotePath.length > 0;
    if (hasLocal === hasRemote) errs.push(`${k}[${i}]: give exactly one of localPath or remotePath`);
    if (a?.sha256 != null && !SHA256.test(a.sha256)) errs.push(`${k}[${i}]: sha256 must be 64 lowercase hex chars`);
    if (k === "plugins" && !/\.jar$/.test(String(a?.localPath ?? a?.remotePath ?? ""))) errs.push(`plugins[${i}]: must be a .jar`);
  }
  for (const [i, d] of (spec.datapacks ?? []).entries()) if (!/^[a-z0-9_.-]{1,64}$/.test(String(d?.name ?? ""))) errs.push(`datapacks[${i}].name must be 1-64 chars of a-z 0-9 _ . -`);
  const pluginNames = new Set<string>();
  for (const p of spec.plugins ?? []) {
    const b = String(p.localPath ?? p.remotePath ?? "").split("/").pop()!;
    if (pluginNames.has(b)) errs.push(`two plugins share the file name ${b}`);
    pluginNames.add(b);
  }
  for (const [i, c] of (spec.rcon ?? []).entries()) {
    const cmd = String(c?.command ?? "");
    if (!cmd.trim() || cmd.length > 200 || /[\r\n]/.test(cmd)) errs.push(`rcon[${i}].command must be one line of 1-200 chars`);
    if (RESERVED_COMMANDS.test(cmd.trim())) errs.push(`rcon[${i}]: '${cmd}' is reserved for the runner`);
    if (c.expect != null && !Array.isArray(c.expect)) errs.push(`rcon[${i}].expect must be an array of strings`);
    if (c.writeFile != null) checkFile(c.writeFile, `rcon[${i}].writeFile`, errs);
    if (c.waitMs != null && !(Number.isInteger(c.waitMs) && c.waitMs >= 0 && c.waitMs <= 30000)) errs.push(`rcon[${i}].waitMs must be 0-30000`);
  }
  if ((spec.files ?? []).length > MAX_SERVER_FILES) errs.push(`files: at most ${MAX_SERVER_FILES}`);
  for (const [i, f] of (spec.files ?? []).entries()) checkFile(f, `files[${i}]`, errs);
  checkMatchers(spec.logMatchers, "logMatchers", errs);
  checkMatchers(spec.logIgnore, "logIgnore", errs);
  if (spec.logMatchers && spec.logMatchers.length === 0) errs.push("logMatchers: an empty list would make the log check vacuous; omit it to use the defaults");
  const t = spec.timeouts ?? {};
  for (const [k, max] of [["bootSec", 600], ["rconSec", 60], ["stopSec", 120], ["totalSec", 900]] as const) {
    const v = t[k];
    if (v != null && !(Number.isFinite(v) && v > 0 && v <= max)) errs.push(`timeouts.${k} must be 1-${max}`);
  }
  const m = spec.memory ?? {};
  if (m.xmxMb != null && !(Number.isInteger(m.xmxMb) && m.xmxMb >= 256 && m.xmxMb <= 1024)) errs.push("memory.xmxMb must be 256-1024 (node-2 allows at most -Xmx1g)");
  if (m.rssCapMb != null && !(Number.isInteger(m.rssCapMb) && m.rssCapMb >= 512 && m.rssCapMb <= 2048)) errs.push("memory.rssCapMb must be 512-2048");
  for (const s of spec.requireStages ?? []) if (!(CHECK_IDS as readonly string[]).includes(s)) errs.push(`requireStages: unknown stage ${s}`);
  if (errs.length || !row) return { ok: false, errors: errs };
  return { ok: true, row: row as PinnedRow };
}

/** Required stages for a spec. The summary uses THIS (what we asked for), not the runner's own flags. */
export function requiredStages(spec: TestFlightSpec): Set<CheckId> {
  const req = new Set<CheckId>(["boot_done", "startup_log_clean", "clean_stop", "no_leaks"]);
  if ((spec.plugins ?? []).length) req.add("plugins_enabled");
  if ((spec.rcon ?? []).length || (spec.datapacks ?? []).length) req.add("rcon_checks");
  for (const s of spec.requireStages ?? []) req.add(s);
  return req;
}

const base = (p: string) => p.split("/").pop()!;

/** Resolve a validated spec for the runner. Local artifacts are mapped to `<root>/inbox/<runId>/<file>`. */
export function resolveSpec(spec: TestFlightSpec, opts: { runId: string; root?: string; lookup?: (id: string) => VersionRow | null }): ResolvedSpec {
  const v = validateSpec(spec, opts.lookup);
  if (!v.ok) throw new Error(`invalid Test Flight spec: ${v.errors.join("; ")}`);
  if (!/^[a-z0-9][a-z0-9-]{5,63}$/.test(opts.runId)) throw new Error("runId must be 6-64 chars of a-z, 0-9, -");
  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const inbox = `${root}/inbox/${opts.runId}`;
  return {
    schema: 1,
    runId: opts.runId,
    version: v.row.id,
    javaRelease: v.row.javaRelease,
    paper: { build: v.row.paperBuild, sha256: v.row.paperServerSha256 },
    plugins: (spec.plugins ?? []).map((p) => ({ path: p.remotePath ?? `${inbox}/${base(p.localPath!)}`, ...(p.sha256 ? { sha256: p.sha256 } : {}) })),
    datapacks: (spec.datapacks ?? []).map((d) => ({ name: d.name, path: d.remotePath ?? `${inbox}/dp-${d.name}` })),
    ...(spec.resourcePack ? { resourcePack: spec.resourcePack } : {}),
    ...(spec.files?.length ? { files: spec.files } : {}),
    rcon: spec.rcon ?? [],
    ...(spec.logMatchers ? { logMatchers: spec.logMatchers } : {}),
    ...(spec.logIgnore ? { logIgnore: spec.logIgnore } : {}),
    timeouts: { ...DEFAULT_TIMEOUTS, ...(spec.timeouts ?? {}) },
    memory: { ...DEFAULT_MEMORY, ...(spec.memory ?? {}) },
    keepDir: !!spec.keepDir,
  };
}
  | { kind: "plugin"; file: string; sha256: string; pluginName: string | null; apiVersion: string | null; descriptor: string | null }
  | { kind: "datapack"; name: string; sha256: string | null; directory: boolean }
  | { kind: "resourcePack"; url: string; sha1: string | null; exercised: false };

export type EngineMeta = {
  runner: string;
  runnerSha256: string;
  node: string;
  host: string;
  kernel: string;
  jdk: { release: number; version: string | null; dist: string; sha256: string };
  paper: { version: string; build: number; sha256: string; channel: string | null };
  isolation: { netns: string; uid: number; noNewPrivs: boolean; nice: number; activeProcessorCount: number };
};

/** Raw runner output. `status` says whether the runner itself completed; `overall` is its own verdict (recomputed by summarize). */
export type TestFlightReport = {
  schema: 1;
  runId: string | null;
  status: "completed" | "busy" | "error";
  version: string | null;
  javaRelease: number | null;
  startedAt: string;
  finishedAt: string | null;
  checks: CheckResult[];
  timings: Record<string, number>;
  bootMs: number | null;
  doneReportedSec: number | null;
  peakRssKb: number | null;
  artifacts: ReportArtifact[];
  engine: EngineMeta | null;
  notes: string[];
  overall: "passed" | "failed" | "incomplete";
};

export type Overall = "passed" | "failed" | "incomplete" | "busy" | "error";

export type TestFlightSummary = {
  version: string;
  overall: Overall;
  /** true only when overall === "passed". */
  success: boolean;
  passed: CheckId[];
  failed: CheckId[];
  /** Required checks that did not run (or "passed" without evidence): any entry here blocks success. */
  skippedRequired: CheckId[];
  notRunOptional: CheckId[];
  reasons: string[];
  bootMs: number | null;
  peakRssKb: number | null;
  runId: string | null;
};

export type MatrixSummary = { overall: Overall; success: boolean; versions: TestFlightSummary[] };

async function stageInner(ctxPath) {
  const ctx = JSON.parse(fs.readFileSync(ctxPath, "utf8"));
  const { spec, plugins, runDir, marker } = ctx;
  const T = Object.assign({ bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 }, spec.timeouts || {});
  const xmx = (spec.memory && spec.memory.xmxMb) || 1024;
  const rssCapKb = ((spec.memory && spec.memory.rssCapMb) || 1800) * 1024;
  const matchers = spec.logMatchers || L.DEFAULT_LOG_MATCHERS;
  const ignores = [...L.DEFAULT_LOG_IGNORES, ...(spec.logIgnore || [])];
  const checks = emptyChecks(requiredFor(spec));
  const C = Object.fromEntries(checks.map((c) => [c.id, c]));
  const notes = [];
  const timings = {};
  const out = { checks, notes, timings, bootMs: null, doneReportedSec: null, peakRssKb: null };
  const save = () => fs.writeFileSync(ctx.out, JSON.stringify(out));

  const { port, rconPort } = L.pickPorts();
  const rconPassword = crypto.randomBytes(18).toString("base64url");
  fs.writeFileSync(path.join(runDir, "eula.txt"), "eula=true\n");
  fs.writeFileSync(path.join(runDir, "server.properties"), L.serverProperties({ port, rconPort, rconPassword, resourcePack: spec.resourcePack }));
  spawnSync("chown", [`${RUN_UID}:${RUN_UID}`, path.join(runDir, "eula.txt"), path.join(runDir, "server.properties")]);
  notes.push(`ports: server ${port}, rcon ${rconPort} (private netns, 127.0.0.1)`);

  const java = path.join(ctx.javaHome, "bin/java");
  const args = ["-n", "10", "setpriv", `--reuid=${RUN_UID}`, `--regid=${RUN_UID}`, "--clear-groups", "--no-new-privs", "--",
    java, marker, `-Xmx${xmx}m`, "-Xms128m", "-XX:+UseSerialGC", "-XX:ActiveProcessorCount=2", "-XX:MaxMetaspaceSize=256m",
    "-XX:ReservedCodeCacheSize=96m", "-XX:+ExitOnOutOfMemoryError", `-Djava.io.tmpdir=${runDir}/tmp`, `-Duser.home=${runDir}`,
    `-DbundlerRepoDir=${ctx.paperDir}`, "-Dpaper.disableChannelLimit=true", "-jar", ctx.paperJar, "--nogui"];
  const consoleLog = path.join(runDir, "console.log");
  const lines = [];
  let partial = "";
  const t0 = now();
  const child = spawn("nice", args, { cwd: runDir, stdio: ["pipe", "pipe", "pipe"], env: { PATH: "/usr/bin:/bin", HOME: runDir, LANG: "C.UTF-8" } });
  const pid = child.pid;
  let exited = null;
  const exitP = new Promise((r) => child.on("exit", (code, sig) => { exited = { code, sig, at: now() }; r(exited); }));
  const onData = (d) => {
    fs.appendFileSync(consoleLog, d);
    const s = partial + d.toString("utf8");
    const parts = s.split(/\r?\n/);
    partial = parts.pop();
    for (const p of parts) lines.push(p.replace(/\x1b\[[0-9;]*m/g, ""));
  };
  child.stdout.on("data", onData);
  child.stderr.on("data", onData);
  child.stdin.on("error", () => {});

  // Watchdog: peak RSS (VmHWM) sampling, RSS cap, hard total timeout. Kills only `pid`, and only if it is our java.
  let peak = 0, killedFor = null;
  const isOurs = () => { try { return fs.readFileSync(`/proc/${pid}/cmdline`, "utf8").split("\0").includes(marker); } catch { return false; } };
  const hardKill = (why) => { if (!exited && isOurs()) { killedFor = killedFor || why; try { process.kill(pid, "SIGKILL"); } catch { /* gone */ } } };
  const sample = () => {
    try {
      const st = fs.readFileSync(`/proc/${pid}/status`, "utf8");
      const hwm = Number((/VmHWM:\s+(\d+)/.exec(st) || [])[1] || 0), rss = Number((/VmRSS:\s+(\d+)/.exec(st) || [])[1] || 0);
      peak = Math.max(peak, hwm, rss);
      if (rss > rssCapKb) hardKill(`RSS ${rss} kB over the cap ${rssCapKb} kB`);
    } catch { /* not started or gone */ }
  };
  const sampler = setInterval(sample, 500);
  const hard = setTimeout(() => hardKill(`hard timeout ${T.totalSec}s`), T.totalSec * 1000);
  const verifyChild = setTimeout(() => { if (!exited && !isOurs()) notes.push(`warning: pid ${pid} cmdline lacks the marker`); }, 3000);

  // (a) boot_done
  let doneIdx = -1;
  const ta = now();
  while (now() - t0 < T.bootSec * 1000 && !exited) {
    doneIdx = L.findDone(lines);
    if (doneIdx >= 0) break;
    await sleep(200);
  }
  if (doneIdx < 0) doneIdx = L.findDone(lines);
  C.boot_done.durationMs = now() - ta;
  if (doneIdx >= 0) {
    out.bootMs = now() - t0;
    out.doneReportedSec = L.doneSeconds(lines[doneIdx]);
    C.boot_done.status = "pass";
    C.boot_done.evidence.push(`L${doneIdx + 1}: ${clip(lines[doneIdx], 200)}`, `wall ${out.bootMs} ms from spawn`);
  } else {
    C.boot_done.status = "fail";
    C.boot_done.evidence.push(exited ? `server exited before Done (code ${exited.code}, signal ${exited.sig})` : `no "Done" line within ${T.bootSec}s`);
    C.boot_done.evidence.push(...lines.slice(-8).map((l) => clip(l, 240)));
  }
  sample();
  save();

  let rcon = null, rconErr = null, pluginReply = null;
  const up = doneIdx >= 0 && !exited;
  if (up) {
    const tr = now();
    try { rcon = await rconConnect(rconPort, rconPassword, T.rconSec * 1000); } catch (e) { rconErr = e.message; }
    timings.rconConnectMs = now() - tr;
    if (rcon && plugins.length) { try { pluginReply = (await rcon.command("plugins", T.rconSec * 1000)).text; } catch (e) { rconErr = e.message; } }
  }

  // (b) plugins_enabled: log evidence is required; the RCON `plugins` listing corroborates (red = disabled -> fail).
  if (plugins.length && doneIdx >= 0) {
    const tb = now();
    const listed = pluginReply != null ? L.parsePluginList(pluginReply) : null;
    let allOk = true;
    for (const p of plugins) {
      if (!p.name) { allOk = false; C.plugins_enabled.evidence.push(`${p.file}: no plugin.yml/paper-plugin.yml name (${p.error || "descriptor missing"})`); continue; }
      const st = L.pluginLogStatus(lines, p.name, lines.length);
      const inList = listed ? (p.name in listed ? listed[p.name] : "absent") : "rcon unavailable";
      const ok = st.enabled && inList !== false && inList !== "absent";
      if (!ok) allOk = false;
      C.plugins_enabled.evidence.push(`${p.name}: ${ok ? "enabled" : "NOT enabled"} (log: enabling=${st.sawEnabling} enableError=${st.enableError} loadError=${st.loadError} disabled=${st.disabledBeforeStop}; rcon plugins: ${inList})`);
      C.plugins_enabled.evidence.push(...st.evidence.slice(0, 4));
    }
    if (pluginReply != null) C.plugins_enabled.evidence.push(`rcon plugins -> ${clip(L.stripColors(pluginReply).replace(/\n/g, " | "), 300)}`);
    C.plugins_enabled.status = allOk ? "pass" : "fail";
    C.plugins_enabled.durationMs = now() - tb;
  } else if (plugins.length) C.plugins_enabled.evidence.push("server never reached Done; plugin state not checked");

  // (c) startup_log_clean: matcher hits from spawn up to and including the Done line.
  if (lines.length) {
    const tc = now();
    const end = doneIdx >= 0 ? doneIdx + 1 : lines.length;
    const { hits, ignored } = L.matchLogDetailed(lines, matchers, ignores, 0, end);
    C.startup_log_clean.status = doneIdx >= 0 ? (hits.length ? "fail" : "pass") : (hits.length ? "fail" : "not_run");
    const igIds = [...new Set(ignored.map((x) => x.ignore))];
    C.startup_log_clean.evidence.push(`${end} startup lines scanned with ${matchers.length} matchers, ${ignores.length} ignores: ${hits.length} hits, ${ignored.length} ignored${igIds.length ? " (" + igIds.join(", ") + ")" : ""}`);
    C.startup_log_clean.evidence.push(...hits.slice(0, 15).map((h) => `L${h.line} [${h.matcher}] ${clip(h.text, 240)}`));
    if (doneIdx < 0 && !hits.length) C.startup_log_clean.evidence.push("startup never finished, so a clean log proves nothing");
    C.startup_log_clean.durationMs = now() - tc;
  }

  // (d) rcon_checks: spec commands plus one auto `datapack list enabled` check per datapack.
  const rchecks = [...(spec.rcon || []).map((c, i) => ({ id: c.id || `rcon-${i + 1}`, ...c }))];
  if ((spec.datapacks || []).length) rchecks.push({ id: "datapacks-enabled", command: "datapack list enabled", expect: spec.datapacks.map((d) => `file/${d.name}`), auto: true });
  if (rchecks.length) {
    const td = now();
    if (!up) C.rcon_checks.evidence.push("server not up; no RCON commands sent");
    else if (!rcon) { C.rcon_checks.status = "fail"; C.rcon_checks.evidence.push(`RCON unavailable: ${rconErr}`); }
    else {
      let allOk = true;
      for (const c of rchecks) {
        try {
          if (c.writeFile) C.rcon_checks.evidence.push(`${c.id}: wrote ${c.writeFile.path} (${writeServerFile(runDir, c.writeFile)} bytes) before the command`);
          if (c.waitMs) await sleep(c.waitMs);
          const r = await rcon.command(c.command, T.rconSec * 1000);
          const ev = L.evalRcon(c, r.text);
          if (!ev.ok && c.required !== false) allOk = false;
          C.rcon_checks.evidence.push(`${c.id} '${c.command}': ${ev.ok ? "ok" : "FAILED"}${ev.missing.length ? " missing " + JSON.stringify(ev.missing) : ""}${ev.forbidden.length ? " forbidden " + JSON.stringify(ev.forbidden) : ""}${c.required === false ? " (optional)" : ""} -> ${clip(L.stripColors(r.text).replace(/\n/g, " | "), 240)}`);
        } catch (e) { if (c.required !== false) allOk = false; C.rcon_checks.evidence.push(`${c.id} '${c.command}': ERROR ${e.message}`); }
      }
      C.rcon_checks.status = allOk ? "pass" : "fail";
    }
    C.rcon_checks.durationMs = now() - td;
  } else C.rcon_checks.evidence.push("no RCON checks in the spec");
