#!/usr/bin/env python3
# Resolve a Maven runtime closure (jar + pom + parent poms), download from Maven Central, verify each file's
# published .sha1, lay out a Maven local repository. Usage: mvnseed.py <outdir> <repoUrl> g:a:v [g:a:v ...]
import sys, os, re, hashlib, urllib.request, xml.etree.ElementTree as ET, json
out, repo, roots = sys.argv[1], sys.argv[2].rstrip('/'), sys.argv[3:]
NS = '{http://maven.apache.org/POM/4.0.0}'
ledger = []
def fetch(g, a, v, ext, required=True):
    rel = f"{g.replace('.','/')}/{a}/{v}/{a}-{v}.{ext}"
    dest = os.path.join(out, rel)
    if os.path.exists(dest): return open(dest,'rb').read()
    try:
        data = urllib.request.urlopen(f"{repo}/{rel}", timeout=60).read()
        sha1 = urllib.request.urlopen(f"{repo}/{rel}.sha1", timeout=60).read().decode().split()[0].strip()
    except Exception as e:
        if required: raise RuntimeError(f"{rel}: {e}")
        return None
    if hashlib.sha1(data).hexdigest() != sha1: raise RuntimeError(f"{rel}: sha1 mismatch")
    os.makedirs(os.path.dirname(dest), exist_ok=True); open(dest,'wb').write(data)
    ledger.append({"path": rel, "sha1": sha1, "sha256": hashlib.sha256(data).hexdigest(), "bytes": len(data)})
    return data
def t(e, name):
    x = e.find(NS+name) if e is not None else None
    return x.text.strip() if x is not None and x.text else None
poms = {}
def model(g, a, v):
    k=(g,a,v)
    if k in poms: return poms[k]
    root = ET.fromstring(fetch(g,a,v,'pom'))
    props = {}; dm = {}
    par = root.find(NS+'parent')
    if par is not None:
        pm = model(t(par,'groupId'), t(par,'artifactId'), t(par,'version'))
        props.update(pm['props']); dm.update(pm['dm'])
    gid = t(root,'groupId') or (t(par,'groupId') if par is not None else None)
    ver = t(root,'version') or (t(par,'version') if par is not None else None)
    props.update({'project.groupId': gid, 'project.version': ver, 'pom.version': ver, 'version': ver, 'project.artifactId': a})
    if par is not None: props['project.parent.version'] = t(par,'version')
    pe = root.find(NS+'properties')
    if pe is not None:
        for c in pe: props[c.tag.replace(NS,'')] = (c.text or '').strip()
    def sub(s):
        for _ in range(10):
            if not s or '${' not in s: break
            s = re.sub(r'\$\{([^}]+)\}', lambda m: props.get(m.group(1), m.group(0)), s)
        return s
    dme = root.find(NS+'dependencyManagement')
    if dme is not None:
        for d in dme.iter(NS+'dependency'):
            dg, da, dv, sc = sub(t(d,'groupId')), sub(t(d,'artifactId')), sub(t(d,'version')), t(d,'scope')
            if sc == 'import' and t(d,'type') == 'pom':
                bm = model(dg, da, dv); 
                for kk, vv in bm['dm'].items(): dm.setdefault(kk, vv)
            else: dm[(dg,da)] = dv
    deps = []
    de = root.find(NS+'dependencies')
    if de is not None:
        for d in de.findall(NS+'dependency'):
            sc = t(d,'scope') or 'compile'; opt = t(d,'optional') == 'true'
            dg, da = sub(t(d,'groupId')), sub(t(d,'artifactId'))
            dv = sub(t(d,'version')) or dm.get((dg,da))
            deps.append((dg, da, dv, sc, opt, t(d,'type') or 'jar', t(d,'classifier')))
    m = {'props': props, 'dm': dm, 'deps': deps, 'packaging': t(root,'packaging') or 'jar'}
    poms[k] = m; return m
seen = set(); order=[]
def walk(g,a,v,depth=0):
    if (g,a) in seen: return
    seen.add((g,a)); order.append(f"{g}:{a}:{v}")
    m = model(g,a,v)
    if m['packaging'] in ('jar','bundle'): fetch(g,a,v,'jar')
    for dg,da,dv,sc,opt,ty,cl in m['deps']:
        if sc in ('compile','runtime') and not opt and ty=='jar' and not cl: walk(dg,da,dv,depth+1)
for r in roots:
    g,a,v = r.split(':'); walk(g,a,v)
json.dump({"repo": repo, "roots": roots, "closure": order, "files": sorted(ledger, key=lambda x: x["path"])}, open(os.path.join(out, "..", os.path.basename(out)+".ledger.json"),"w"), indent=1)
print("\n".join(order)); print(len(ledger), "files")
EOF
