input.content:
// Archetype templates of the creature pipeline (Cyrus R3): a hand-tuned bone tree + cubes + procedural clips per
// archetype, so a RigSpec in template form ({ archetype, template: { features, height }, skin: { palette } }) always
// compiles to a recognisable, well-proportioned creature. Pure data builders, no imports (spec.ts validates the output
// with the same rules as an explicit RigSpec). Coordinates: Blockbench units, absolute, y up, the creature faces north
// (-z); its right side is +x. Rotations are degrees, right-handed per axis (Blockbench 5 / BetterModel): +x swings a
// hanging limb forward and tips a standing part backward; +z swings the right (+x) arm outward.

type V3 = [number, number, number];
type Decal = { op: "px"; x: number; y: number; c: string } | { op: "rect"; x: number; y: number; w: number; h: number; c: string } | { op: "line"; x1: number; y1: number; x2: number; y2: number; c: string };
type FaceName = "north" | "east" | "south" | "west" | "up" | "down";
type TCube = { from: V3; to: V3; material: string; shade?: "solid" | "fade"; fadeTo?: string; inflate?: number; decals?: Partial<Record<FaceName, Decal[]>> };
type TBone = { name: string; parent: string | null; pivot: V3; rotation?: V3; tag?: "none" | "head" | "glow"; cubes: TCube[] };
type Wave = { amp: V3; offset?: V3; cycles?: number; phase?: number };
type Key = { t: number; v: V3; ease?: "linear" | "smooth" };
type TTrack = { bone: string; channel: "rotation" | "position" | "scale"; wave?: Wave; keys?: Key[] };
type TClip = { length: number; loop: boolean; tracks: TTrack[] };

export const TEMPLATE_ARCHETYPES = ["humanoid", "floating_ghost", "quadruped"] as const;
export type TemplateArchetype = (typeof TEMPLATE_ARCHETYPES)[number];
export const TEMPLATE_FEATURES: Readonly<Record<TemplateArchetype, readonly string[]>> = {
  humanoid: ["horns", "hood", "cape"],
  floating_ghost: ["hood", "crown", "claws"],
  quadruped: ["horns", "mane", "spikes"],
};
/** Colours each template paints with (the RigSpec palette must define them; extra keys are fine for decals). */
export const TEMPLATE_PALETTE_KEYS: Readonly<Record<TemplateArchetype, readonly string[]>> = {
  humanoid: ["skin", "cloth", "cloth_dark", "accent", "hair", "eye"],
  floating_ghost: ["skin", "robe", "shadow", "hair", "eye", "mouth"],
  quadruped: ["fur", "fur_dark", "belly", "nose", "eye", "accent"],
};

const r2 = (v: number) => Math.round(v * 1000) / 1000;
const ceil = (v: number) => Math.max(1, Math.ceil(v - 1e-9));
/** Face pixel size (same rule as spec.ts faceSize). */
function face(c: { from: V3; to: V3 }, f: FaceName): [number, number] {
  const w = ceil(c.to[0] - c.from[0]), h = ceil(c.to[1] - c.from[1]), d = ceil(c.to[2] - c.from[2]);
  return f === "north" || f === "south" ? [w, h] : f === "east" || f === "west" ? [d, h] : [w, d];
}
/** Vertical stretch below `neck` (height multiplier); everything above the neck only moves up. */
const stretch = (h: number, neck: number) => (y: number) => r2(y <= neck ? y * h : y + neck * (h - 1));
const mapCube = (Y: (y: number) => number, c: TCube): TCube => ({ ...c, from: [c.from[0], Y(c.from[1]), c.from[2]], to: [c.to[0], Y(c.to[1]), c.to[2]] });
const mapBone = (Y: (y: number) => number, b: TBone): TBone => ({ ...b, pivot: [b.pivot[0], Y(b.pivot[1]), b.pivot[2]], cubes: b.cubes.map((c) => mapCube(Y, c)) });
const wave = (bone: string, channel: TTrack["channel"], w: Wave): TTrack => ({ bone, channel, wave: { cycles: 1, phase: 0, ...w } });
const keys = (bone: string, channel: TTrack["channel"], ks: [number, V3, ("linear" | "smooth")?][]): TTrack => ({ bone, channel, keys: ks.map(([t, v, e]) => ({ t, v, ease: e ?? "smooth" })) });
/** The common ending of every death clip: hold, then shrink to nothing (the plugin removes the mob afterwards). */
const vanish = (bone: string, from = 0.8): TTrack => keys(bone, "scale", [[0, [1, 1, 1]], [from, [1, 1, 1]], [1, [0.02, 0.02, 0.02], "linear"]]);

/** Add pixel details AFTER the stretch, sized from the real faces (so decals always fit). */
function decorate(bones: TBone[], name: string, cubeIndex: number, fn: (c: TCube, size: (f: FaceName) => [number, number]) => Partial<Record<FaceName, Decal[]>>) {
  const b = bones.find((x) => x.name === name);
  if (!b || !b.cubes[cubeIndex]) return;
  const c = b.cubes[cubeIndex];
  c.decals = fn(c, (f) => face(c, f));
}

