    return { north: boot(fw), south: boot(fw), east: boot(sw), west: boot(sw), down: [{ op: "rect", x: 0, y: 0, w: sz("down")[0], h: sz("down")[1], c: "accent" }] };
  });
  const capeTr = has("cape");
  const animations: Record<string, TClip> = {
