      wave("body", "position", { amp: [0, 0.3, 0] }),
      wave("head", "rotation", { amp: [2.5, 3, 0], phase: 0.25 }),
      wave("arm_r", "rotation", { amp: [3, 0, 2], offset: [0, 0, 3] }),
      wave("arm_l", "rotation", { amp: [3, 0, -2], offset: [0, 0, -3], phase: 0.5 }),
      ...(capeTr ? [wave("cape", "rotation", { amp: [3, 0, 0], offset: [-4, 0, 0], phase: 0.3 })] : []),
    ] },
    walk: { length: 1, loop: true, tracks: [
      wave("leg_r", "rotation", { amp: [32, 0, 0] }),
      wave("leg_l", "rotation", { amp: [32, 0, 0], phase: 0.5 }),
      wave("arm_r", "rotation", { amp: [28, 0, 0], offset: [0, 0, 2], phase: 0.5 }),
      wave("arm_l", "rotation", { amp: [28, 0, 0], offset: [0, 0, -2] }),
      wave("body", "position", { amp: [0, 0.6, 0], cycles: 2, phase: 0.25 }),
      wave("body", "rotation", { amp: [0, 4, 0] }),
      ...(capeTr ? [wave("cape", "rotation", { amp: [5, 0, 0], offset: [-16, 0, 0], cycles: 2 })] : []),
    ] },
    attack: { length: 0.6, loop: false, tracks: [
      keys("arm_r", "rotation", [[0, [0, 0, 0]], [0.4, [165, 0, 10]], [0.6, [45, 0, 0], "linear"], [1, [0, 0, 0]]]),
      keys("arm_l", "rotation", [[0, [0, 0, 0]], [0.4, [-20, 0, -10]], [0.6, [25, 0, 0]], [1, [0, 0, 0]]]),
      keys("body", "rotation", [[0, [0, 0, 0]], [0.4, [6, -14, 0]], [0.6, [-14, 10, 0], "linear"], [1, [0, 0, 0]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.4, [8, 10, 0]], [0.6, [-6, -6, 0]], [1, [0, 0, 0]]]),
    ] },
    hurt: { length: 0.4, loop: false, tracks: [
      keys("body", "rotation", [[0, [0, 0, 0]], [0.3, [12, 0, 6]], [1, [0, 0, 0]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.3, [15, 0, -8]], [1, [0, 0, 0]]]),
      keys("arm_r", "rotation", [[0, [0, 0, 0]], [0.3, [-15, 0, 18]], [1, [0, 0, 0]]]),
      keys("arm_l", "rotation", [[0, [0, 0, 0]], [0.3, [-15, 0, -18]], [1, [0, 0, 0]]]),
    ] },
    death: { length: 1.6, loop: false, tracks: [
      keys("root", "rotation", [[0, [0, 0, 0]], [0.15, [-8, 0, 0]], [0.6, [90, 0, 0], "linear"], [0.7, [84, 0, 0]], [0.8, [90, 0, 0]], [1, [90, 0, 0]]]),
      keys("arm_r", "rotation", [[0, [0, 0, 0]], [0.6, [150, 0, 25]], [1, [160, 0, 30]]]),
      keys("arm_l", "rotation", [[0, [0, 0, 0]], [0.6, [150, 0, -25]], [1, [160, 0, -30]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.6, [-20, 0, 0]], [1, [-25, 20, 0]]]),
      vanish("root", 0.82),
    ] },
  };
  return { bones, animations };
