  if (has("spikes")) raw.find((b) => b.name === "body")!.cubes.push(
    { from: [-0.5, 14, -4], to: [0.5, 16, -2.5], material: "accent" }, { from: [-0.5, 14, -0.75], to: [0.5, 16.5, 0.75], material: "accent" }, { from: [-0.5, 14, 2.5], to: [0.5, 15.75, 4], material: "accent" },
  );
