      keys("head", "rotation", [[0, [0, 0, 0]], [0.3, [14, -10, 0]], [1, [0, 0, 0]]]),
    ] },
    death: { length: 1.5, loop: false, tracks: [
      keys("root", "rotation", [[0, [0, 0, 0]], [0.2, [0, 0, -8]], [0.6, [0, 0, 90], "linear"], [0.7, [0, 0, 84]], [0.8, [0, 0, 90]], [1, [0, 0, 90]]]),
      keys("leg_fr", "rotation", [[0, [0, 0, 0]], [0.6, [-20, 0, 0]], [1, [-30, 0, 0]]]),
      keys("leg_bl", "rotation", [[0, [0, 0, 0]], [0.6, [20, 0, 0]], [1, [30, 0, 0]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.6, [-10, 0, 0]], [1, [-15, 0, 0]]]),
      vanish("root", 0.82),
    ] },
  };
  return { bones, animations };
}

/** Expand a template-form RigSpec into explicit bones + clips (deterministic). */
export function expandTemplate(archetype: TemplateArchetype, t: { features?: string[]; height?: number }): { bones: TBone[]; animations: Record<string, TClip> } {
  const f = [...new Set(t.features ?? [])].sort();
  const h = t.height ?? 1;
  if (archetype === "floating_ghost") return floatingGhost(f, h);
  if (archetype === "humanoid") return humanoid(f, h);
  return quadruped(f, h);
}

