    { name: "hair_back", parent: "hair", pivot: [0, 31, 3.5], cubes: [{ from: [-4, 15, 2.5], to: [4, 31, 4.5], material: "hair", shade: "fade", fadeTo: "shadow" }] },
    { name: "arm_r", parent: "body", pivot: [4.5, 25, 0], rotation: [0, 0, 8], cubes: [
      { from: [3.5, 19, -1.5], to: [5.5, 25.5, 1.5], material: "robe" },
      { from: [3.75, 12, -1], to: [5.25, 19, 1], material: "skin" },
    ] },
    { name: "arm_l", parent: "body", pivot: [-4.5, 25, 0], rotation: [0, 0, -8], cubes: [
      { from: [-5.5, 19, -1.5], to: [-3.5, 25.5, 1.5], material: "robe" },
      { from: [-5.25, 12, -1], to: [-3.75, 19, 1], material: "skin" },
    ] },
  ];
  if (has("hood")) raw.find((b) => b.name === "hair")!.cubes.push({ from: [-4.5, 27, -1.5], to: [4.5, 34.5, 4.75], material: "robe", shade: "fade", fadeTo: "shadow" });
  if (has("crown")) raw.push({ name: "crown", parent: "head", pivot: [0, 34, 0], tag: "glow", cubes: [
    { from: [-3, 34, -3], to: [-2, 35.5, -2], material: "eye" }, { from: [-0.5, 34, -3.25], to: [0.5, 36, -2.25], material: "eye" }, { from: [2, 34, -3], to: [3, 35.5, -2], material: "eye" },
  ] });
  const bones = raw.map((b) => mapBone(Y, b));
  // face: hollow cheeks, an open wailing mouth, a dark brow line over the glowing eyes
  decorate(bones, "head", 0, (_c, sz) => {
    const [w, hh] = sz("north");
    return { north: [
      { op: "rect", x: 1, y: 2, w: 2, h: 1, c: "shadow" }, { op: "rect", x: w - 3, y: 2, w: 2, h: 1, c: "shadow" },
      { op: "rect", x: Math.floor(w / 2) - 1, y: hh - 3, w: 2, h: 3, c: "mouth" },
      { op: "px", x: 1, y: hh - 3, c: "shadow" }, { op: "px", x: w - 2, y: hh - 3, c: "shadow" },
    ], up: [{ op: "rect", x: 0, y: 0, w: sz("up")[0], h: sz("up")[1], c: "hair" }] };
  });
  decorate(bones, "body", 0, (_c, sz) => {
    const [w, hh] = sz("north");
    const mid = Math.floor(w / 2);
    return { north: [
      { op: "line", x1: 0, y1: 0, x2: mid - 1, y2: Math.min(hh - 1, 3), c: "shadow" }, { op: "line", x1: w - 1, y1: 0, x2: mid, y2: Math.min(hh - 1, 3), c: "shadow" },
      { op: "rect", x: mid - 1, y: Math.min(hh - 1, 4), w: 2, h: Math.max(1, hh - 5), c: "shadow" },
    ] };
  });
  decorate(bones, "skirt", 0, (_c, sz) => {
    const [w, hh] = sz("north");
    const tatter = (fw: number): Decal[] => Array.from({ length: Math.floor(fw / 2) }, (_, i) => ({ op: "px" as const, x: i * 2 + 1, y: hh - 1, c: "shadow" }));
    return { north: tatter(w), south: tatter(sz("south")[0]), east: tatter(sz("east")[0]), west: tatter(sz("west")[0]) };
