      wave("hair_back", "rotation", { amp: [4, 0, 2], offset: [-18, 0, 0], cycles: 2, phase: 0.2 }),
      wave("arm_r", "rotation", { amp: [5, 0, 2], offset: [-18, 0, 6], cycles: 2 }),
      wave("arm_l", "rotation", { amp: [5, 0, -2], offset: [-18, 0, -6], cycles: 2, phase: 0.5 }),
    ] },
    attack: { length: 0.8, loop: false, tracks: [
      keys("arm_r", "rotation", [[0, [0, 0, 0]], [0.3, [120, 0, 25]], [0.5, [80, 0, 6]], [1, [0, 0, 0]]]),
      keys("arm_l", "rotation", [[0, [0, 0, 0]], [0.3, [120, 0, -25]], [0.5, [80, 0, -6]], [1, [0, 0, 0]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.3, [18, 0, 0]], [0.5, [-14, 0, 0]], [1, [0, 0, 0]]]),
      keys("body", "position", [[0, [0, 4, 0]], [0.3, [0, 5.5, 2]], [0.5, [0, 3.5, -5]], [1, [0, 4, 0]]]),
      keys("hair_back", "rotation", [[0, [-6, 0, 0]], [0.5, [-35, 0, 0]], [1, [-6, 0, 0]]]),
    ] },
    hurt: { length: 0.4, loop: false, tracks: [
      keys("body", "rotation", [[0, [0, 0, 0]], [0.3, [16, 0, 6]], [1, [0, 0, 0]]]),
      keys("body", "position", [[0, [0, 4, 0]], [0.3, [0, 4.5, 2.5]], [1, [0, 4, 0]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.3, [12, 0, -8]], [1, [0, 0, 0]]]),
    ] },
    death: { length: 1.8, loop: false, tracks: [
      keys("body", "rotation", [[0, [0, 0, 0]], [0.25, [24, 0, 0]], [1, [-20, 200, 0]]]),
      keys("body", "position", [[0, [0, 4, 0]], [0.25, [0, 7, 0]], [1, [0, -12, 0]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.25, [30, 0, 0]], [1, [10, 0, 0]]]),
      keys("arm_r", "rotation", [[0, [0, 0, 0]], [0.25, [150, 0, 30]], [1, [40, 0, 60]]]),
      keys("arm_l", "rotation", [[0, [0, 0, 0]], [0.25, [150, 0, -30]], [1, [40, 0, -60]]]),
      vanish("body", 0.7),
    ] },
  };
  return { bones, animations };
}

// --------------------------------------------------------------------------------------------------- humanoid ----
function humanoid(features: string[], h: number): { bones: TBone[]; animations: Record<string, TClip> } {
  const Y = stretch(h, 24);
  const has = (f: string) => features.includes(f);
  const raw: TBone[] = [
    { name: "root", parent: null, pivot: [0, 0, 0], cubes: [] },
    { name: "body", parent: "root", pivot: [0, 12, 0], cubes: [{ from: [-4, 12, -2], to: [4, 24, 2], material: "cloth" }] },
    { name: "head", parent: "body", pivot: [0, 24, 0], tag: "head", cubes: [{ from: [-4, 24, -4], to: [4, 32, 4], material: "skin" }] },
    { name: "eyes", parent: "head", pivot: [0, 28, -4], tag: "glow", cubes: [
      { from: [-3, 27.5, -4.2], to: [-1, 28.5, -4], material: "eye" },
      { from: [1, 27.5, -4.2], to: [3, 28.5, -4], material: "eye" },
    ] },
    { name: "arm_r", parent: "body", pivot: [5, 22, 0], cubes: [{ from: [4, 12, -2], to: [8, 24, 2], material: "cloth" }] },
    { name: "arm_l", parent: "body", pivot: [-5, 22, 0], cubes: [{ from: [-8, 12, -2], to: [-4, 24, 2], material: "cloth" }] },
    { name: "leg_r", parent: "root", pivot: [2, 12, 0], cubes: [{ from: [0.1, 0, -2], to: [4, 12, 2], material: "cloth_dark" }] },
    { name: "leg_l", parent: "root", pivot: [-2, 12, 0], cubes: [{ from: [-4, 0, -2], to: [-0.1, 12, 2], material: "cloth_dark" }] },
  ];
  if (has("horns")) raw.push({ name: "horns", parent: "head", pivot: [0, 32, 0], cubes: [
    { from: [-4, 31, -2], to: [-2.5, 34, -0.5], material: "accent" }, { from: [-4.5, 33.5, -1.75], to: [-3.25, 36, -0.75], material: "accent" },
    { from: [2.5, 31, -2], to: [4, 34, -0.5], material: "accent" }, { from: [3.25, 33.5, -1.75], to: [4.5, 36, -0.75], material: "accent" },
  ] });
  if (has("hood")) raw.find((b) => b.name === "head")!.cubes.push({ from: [-4.5, 25.5, -3], to: [4.5, 32.75, 4.5], material: "cloth", shade: "fade", fadeTo: "cloth_dark" });
  if (has("cape")) raw.push({ name: "cape", parent: "body", pivot: [0, 24, 2.25], rotation: [-4, 0, 0], cubes: [{ from: [-4.5, 5, 2.25], to: [4.5, 24, 3.25], material: "cloth_dark", shade: "fade", fadeTo: "accent" }] });
  const bones = raw.map((b) => mapBone(Y, b));
  decorate(bones, "head", 0, (_c, sz) => {
    const [w, hh] = sz("north"), [sw] = sz("east"), [uw, ud] = sz("up");
    return {
      north: [
        { op: "rect", x: 0, y: 0, w, h: 2, c: "hair" }, { op: "rect", x: 1, y: 3, w: 2, h: 1, c: "hair" }, { op: "rect", x: w - 3, y: 3, w: 2, h: 1, c: "hair" },
        { op: "rect", x: Math.floor(w / 2) - 1, y: hh - 2, w: 2, h: 1, c: "cloth_dark" },
      ],
      up: [{ op: "rect", x: 0, y: 0, w: uw, h: ud, c: "hair" }],
      east: [{ op: "rect", x: 0, y: 0, w: sw, h: 3, c: "hair" }], west: [{ op: "rect", x: 0, y: 0, w: sw, h: 3, c: "hair" }],
      south: [{ op: "rect", x: 0, y: 0, w, h: Math.max(3, hh - 2), c: "hair" }],
    };
  });
  decorate(bones, "body", 0, (_c, sz) => {
    const [w, hh] = sz("north"), [sw] = sz("east");
    const belt = Math.max(1, hh - 3);
    const ring = (fw: number): Decal[] => [{ op: "rect", x: 0, y: belt, w: fw, h: 1, c: "accent" }];
    return { north: [...ring(w), { op: "rect", x: Math.floor(w / 2) - 1, y: belt, w: 2, h: 1, c: "hair" }, { op: "rect", x: Math.floor(w / 2) - 2, y: 0, w: 4, h: 1, c: "skin" }], south: ring(w), east: ring(sw), west: ring(sw) };
  });
  for (const arm of ["arm_r", "arm_l"]) decorate(bones, arm, 0, (_c, sz) => {
    const [fw, fh] = sz("north"), [sw] = sz("east");
    const hand = (x: number): Decal[] => [{ op: "rect", x: 0, y: fh - 3, w: x, h: 3, c: "skin" }, { op: "rect", x: 0, y: fh - 4, w: x, h: 1, c: "accent" }];
    return { north: hand(fw), south: hand(fw), east: hand(sw), west: hand(sw), down: [{ op: "rect", x: 0, y: 0, w: sz("down")[0], h: sz("down")[1], c: "skin" }] };
  });
