}

// -------------------------------------------------------------------------------------------------- quadruped ----
function quadruped(features: string[], h: number): { bones: TBone[]; animations: Record<string, TClip> } {
  const Y = stretch(h, 7);
  const has = (f: string) => features.includes(f);
  const raw: TBone[] = [
    { name: "root", parent: null, pivot: [0, 0, 0], cubes: [] },
    { name: "body", parent: "root", pivot: [0, 11, 0], cubes: [{ from: [-4, 7, -7], to: [4, 14, 7], material: "fur" }] },
    { name: "head", parent: "body", pivot: [0, 12, -7], tag: "head", cubes: [
      { from: [-3.5, 9, -13], to: [3.5, 15.5, -7], material: "fur" },
      { from: [-2, 9, -16.5], to: [2, 12.25, -13], material: "belly" },
      { from: [-3.5, 15.5, -10.5], to: [-1.5, 18, -9], material: "fur_dark" },
      { from: [1.5, 15.5, -10.5], to: [3.5, 18, -9], material: "fur_dark" },
    ] },
    { name: "eyes", parent: "head", pivot: [0, 13, -13], tag: "glow", cubes: [
      { from: [-3, 12.75, -13.2], to: [-1.5, 13.75, -13], material: "eye" },
      { from: [1.5, 12.75, -13.2], to: [3, 13.75, -13], material: "eye" },
    ] },
    { name: "leg_fr", parent: "body", pivot: [2.5, 7, -4.5], cubes: [{ from: [1, 0, -6], to: [4, 7, -3], material: "fur" }] },
    { name: "leg_fl", parent: "body", pivot: [-2.5, 7, -4.5], cubes: [{ from: [-4, 0, -6], to: [-1, 7, -3], material: "fur" }] },
    { name: "leg_br", parent: "body", pivot: [2.5, 7, 4.5], cubes: [{ from: [1, 0, 3], to: [4, 7, 6], material: "fur" }] },
    { name: "leg_bl", parent: "body", pivot: [-2.5, 7, 4.5], cubes: [{ from: [-4, 0, 3], to: [-1, 7, 6], material: "fur" }] },
    { name: "tail", parent: "body", pivot: [0, 13, 7], rotation: [-25, 0, 0], cubes: [{ from: [-1, 12, 7], to: [1, 14, 13], material: "fur", shade: "fade", fadeTo: "fur_dark" }] },
  ];
  if (has("horns")) raw.find((b) => b.name === "head")!.cubes.push(
    { from: [-3.25, 15, -12.5], to: [-2, 17, -11], material: "accent" }, { from: [2, 15, -12.5], to: [3.25, 17, -11], material: "accent" },
  );
  if (has("mane")) raw.find((b) => b.name === "body")!.cubes.push({ from: [-4.5, 9.5, -8], to: [4.5, 15.5, -3.5], material: "fur_dark" });
  if (has("spikes")) raw.find((b) => b.name === "body")!.cubes.push(
    { from: [-0.5, 14, -4], to: [0.5, 16, -2.5], material: "accent" }, { from: [-0.5, 14, -0.75], to: [0.5, 16.5, 0.75], material: "accent" }, { from: [-0.5, 14, 2.5], to: [0.5, 15.75, 4], material: "accent" },
  );
  const bones = raw.map((b) => mapBone(Y, b));
  decorate(bones, "body", 0, (_c, sz) => {
    const [uw, ud] = sz("up"), [dw, dd] = sz("down"), [sw, sh] = sz("east");
    const stripes = (fw: number): Decal[] => [0.25, 0.5, 0.75].map((f) => ({ op: "rect" as const, x: Math.floor(fw * f), y: 0, w: 1, h: Math.max(1, Math.floor(sh / 3)), c: "fur_dark" }));
    return {
      up: [{ op: "rect", x: Math.floor(uw / 2) - 1, y: 0, w: 2, h: ud, c: "fur_dark" }],
      down: [{ op: "rect", x: 1, y: 1, w: Math.max(1, dw - 2), h: Math.max(1, dd - 2), c: "belly" }],
      east: [...stripes(sw), { op: "rect", x: 0, y: sh - 1, w: sw, h: 1, c: "belly" }], west: [...stripes(sw), { op: "rect", x: 0, y: sh - 1, w: sw, h: 1, c: "belly" }],
    };
  });
  decorate(bones, "head", 0, (_c, sz) => {
    const [w, hh] = sz("north"), [uw, ud] = sz("up");
    return {
      north: [{ op: "rect", x: 0, y: 2, w: 3, h: 1, c: "fur_dark" }, { op: "rect", x: w - 3, y: 2, w: 3, h: 1, c: "fur_dark" }, { op: "rect", x: 2, y: hh - 2, w: w - 4, h: 2, c: "belly" }],
      up: [{ op: "rect", x: Math.floor(uw / 2) - 1, y: 0, w: 2, h: ud, c: "fur_dark" }],
    };
  });
  decorate(bones, "head", 1, (_c, sz) => {
    const [w, hh] = sz("north");
    return { north: [{ op: "rect", x: 1, y: 0, w: Math.max(1, w - 2), h: 1, c: "nose" }, { op: "rect", x: 0, y: hh - 1, w, h: 1, c: "nose" }, { op: "px", x: 0, y: hh - 2, c: "accent" }, { op: "px", x: w - 1, y: hh - 2, c: "accent" }] };
  });
  for (const leg of ["leg_fr", "leg_fl", "leg_br", "leg_bl"]) decorate(bones, leg, 0, (_c, sz) => {
    const [fw, fh] = sz("north"), [sw] = sz("east");
    const paw = (x: number): Decal[] => [{ op: "rect", x: 0, y: fh - 2, w: x, h: 2, c: "fur_dark" }];
    return { north: [...paw(fw), { op: "px", x: 0, y: fh - 1, c: "accent" }, { op: "px", x: fw - 1, y: fh - 1, c: "accent" }], south: paw(fw), east: paw(sw), west: paw(sw), down: [{ op: "rect", x: 0, y: 0, w: sz("down")[0], h: sz("down")[1], c: "fur_dark" }] };
  });
  const animations: Record<string, TClip> = {
    idle: { length: 3, loop: true, tracks: [
      wave("body", "position", { amp: [0, 0.25, 0] }),
      wave("body", "scale", { amp: [0.015, 0.02, 0], offset: [0, 0, 0] }),
      wave("head", "rotation", { amp: [3, 6, 0], phase: 0.3 }),
      wave("tail", "rotation", { amp: [4, 14, 0], cycles: 2 }),
    ] },
    walk: { length: 0.8, loop: true, tracks: [
      wave("leg_fr", "rotation", { amp: [28, 0, 0] }),
      wave("leg_bl", "rotation", { amp: [28, 0, 0] }),
      wave("leg_fl", "rotation", { amp: [28, 0, 0], phase: 0.5 }),
      wave("leg_br", "rotation", { amp: [28, 0, 0], phase: 0.5 }),
      wave("body", "position", { amp: [0, 0.4, 0], cycles: 2 }),
      wave("head", "rotation", { amp: [3, 0, 0], cycles: 2, phase: 0.2 }),
      wave("tail", "rotation", { amp: [6, 16, 0], cycles: 2 }),
    ] },
    attack: { length: 0.6, loop: false, tracks: [
      keys("body", "position", [[0, [0, 0, 0]], [0.35, [0, -0.5, 2]], [0.55, [0, 0.5, -4], "linear"], [1, [0, 0, 0]]]),
      keys("body", "rotation", [[0, [0, 0, 0]], [0.35, [8, 0, 0]], [0.55, [-5, 0, 0]], [1, [0, 0, 0]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.35, [22, 0, 0]], [0.55, [-16, 0, 0], "linear"], [1, [0, 0, 0]]]),
      keys("leg_fr", "rotation", [[0, [0, 0, 0]], [0.35, [30, 0, 0]], [0.55, [-20, 0, 0]], [1, [0, 0, 0]]]),
      keys("leg_fl", "rotation", [[0, [0, 0, 0]], [0.35, [30, 0, 0]], [0.55, [-20, 0, 0]], [1, [0, 0, 0]]]),
    ] },
    hurt: { length: 0.4, loop: false, tracks: [
      keys("body", "rotation", [[0, [0, 0, 0]], [0.3, [-6, 0, 8]], [1, [0, 0, 0]]]),
      keys("body", "position", [[0, [0, 0, 0]], [0.3, [0, 0.5, 1.5]], [1, [0, 0, 0]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.3, [14, -10, 0]], [1, [0, 0, 0]]]),
    ] },
    death: { length: 1.5, loop: false, tracks: [
      keys("root", "rotation", [[0, [0, 0, 0]], [0.2, [0, 0, -8]], [0.6, [0, 0, 90], "linear"], [0.7, [0, 0, 84]], [0.8, [0, 0, 90]], [1, [0, 0, 90]]]),
      keys("leg_fr", "rotation", [[0, [0, 0, 0]], [0.6, [-20, 0, 0]], [1, [-30, 0, 0]]]),
      keys("leg_bl", "rotation", [[0, [0, 0, 0]], [0.6, [20, 0, 0]], [1, [30, 0, 0]]]),
      keys("head", "rotation", [[0, [0, 0, 0]], [0.6, [-10, 0, 0]], [1, [-15, 0, 0]]]),
      vanish("root", 0.82),
    ] },
  };
  return { bones, animations };
}

/** Expand a template-form RigSpec into explicit bones + clips (deterministic). */
export function expandTemplate(archetype: TemplateArchetype, t: { features?: string[]; height?: number }): { bones: TBone[]; animations: Record<string, TClip> } {
  const f = [...new Set(t.features ?? [])].sort();
  const h = t.height ?? 1;
  if (archetype === "floating_ghost") return floatingGhost(f, h);
  if (archetype === "humanoid") return humanoid(f, h);
  return quadruped(f, h);
}

