export const MAX_OPS = 400;
export const MAX_PALETTE = 24;''','''export const TEXTURE_SIZES = [16, 32, 64] as const;
export const MAX_OPS = 400;
export const MAX_PALETTE = 24;
// Creature skin sheets (Cyrus R3, lib/cyrus/creature/compile.ts): the ONLY place the limits are raised. A skin is a
// UV atlas of many box-unwrapped cubes, so it needs a bigger canvas and more (generated) ops; the item profile above
// is unchanged and stays the default. Skins have their own quality bar (lib/cyrus/creature/quality.ts).
export const SKIN_TEXTURE_SIZES = [64, 128] as const;
export const MAX_SKIN_OPS = 3000;
export const MAX_SKIN_PALETTE = 96;
export type TextureProfile = "item" | "skin";''')
s=s.replace('''  size: (typeof TEXTURE_SIZES)[number];''','''  size: (typeof TEXTURE_SIZES)[number] | (typeof SKIN_TEXTURE_SIZES)[number];''')
s=s.replace('''export function checkSpec(raw: unknown): Checked {''','''export function checkSpec(raw: unknown, opts: { profile?: TextureProfile } = {}): Checked {
  const skin = opts.profile === "skin";
  const sizes: readonly number[] = skin ? SKIN_TEXTURE_SIZES : TEXTURE_SIZES;
  const maxOps = skin ? MAX_SKIN_OPS : MAX_OPS;
  const maxPalette = skin ? MAX_SKIN_PALETTE : MAX_PALETTE;''')
s=s.replace('''  if (!(TEXTURE_SIZES as readonly number[]).includes(r.size as number)) return { ok: false, error: "size must be 16, 32 or 64" };''','''  if (!sizes.includes(r.size as number)) return { ok: false, error: skin ? "size must be 64 or 128" : "size must be 16, 32 or 64" };''')
s=s.replace('''  if (entries.length === 0 || entries.length > MAX_PALETTE) return { ok: false, error: `palette needs 1-${MAX_PALETTE} colours` };''','''  if (entries.length === 0 || entries.length > maxPalette) return { ok: false, error: `palette needs 1-${maxPalette} colours` };''')
s=s.replace('''  if (!Array.isArray(r.ops) || r.ops.length === 0 || r.ops.length > MAX_OPS) return { ok: false, error: `ops needs 1-${MAX_OPS} entries` };''','''  if (!Array.isArray(r.ops) || r.ops.length === 0 || r.ops.length > maxOps) return { ok: false, error: `ops needs 1-${maxOps} entries` };''')
open(p,'w').write(s)
EOF
