import { encodePng } from "../textures/png";
import { render, type Raster } from "../textures/render";
import { FACES, faceSize, modelKey, type Bone, type Clip, type Cube, type Face, type RigSpec, type Track } from "./spec";

export const COMPILER_VERSION = "rig-c1";
