// Render review images for RigSpecs: <out>/<name>.preview.png (3x3 contact sheet), <name>.skin.png (sheet x4),
// <name>.png (the real skin), <name>.bbmodel. Pure, no network.
//   npx tsx scripts/cyrus/creature-preview.ts <out dir> <rigspec.json...> [--ns nx_xxxxxxxx]
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { checkRigSpec } from "../../lib/cyrus/creature/spec";
import { compileCreature } from "../../lib/cyrus/creature/compile";
import { previewSheet, skinSheetPng } from "../../lib/cyrus/creature/preview";
import { skinQuality } from "../../lib/cyrus/creature/quality";

const args = process.argv.slice(2);
const nsAt = args.indexOf("--ns");
const ns = nsAt >= 0 ? args.splice(nsAt, 2)[1] : "nx_r6cr34tr";
const [out, ...files] = args;
mkdirSync(out, { recursive: true });
for (const f of files) {
  const c = checkRigSpec(JSON.parse(readFileSync(f, "utf8")), { namespace: ns });
  if (!c.ok) { console.error(`${f}: ${c.error}`); process.exitCode = 1; continue; }
  const r = compileCreature(c.spec, ns);
  if (!r.ok) { console.error(`${f}: ${r.error}`); process.exitCode = 1; continue; }
  const cr = r.creature;
  const name = path.basename(f, ".json");
  writeFileSync(path.join(out, `${name}.bbmodel`), cr.bbmodel);
  writeFileSync(path.join(out, `${name}.png`), cr.png);
  writeFileSync(path.join(out, `${name}.skin.png`), skinSheetPng(cr.raster, 4));
  writeFileSync(path.join(out, `${name}.preview.png`), previewSheet(c.spec, cr.layout, cr.raster).png);
  console.log(JSON.stringify({ name, key: cr.key, stats: cr.stats, bbmodelSha256: cr.bbmodelSha256, pngSha256: cr.pngSha256, quality: skinQuality(cr.raster, cr.layout), warnings: c.warnings }));
}
