// Skin quality bar (Cyrus R3, version sk-1): runs on the rendered skin sheet of every compiled creature. A skin is a
// UV atlas, not an item icon, so the item bar (textures/quality.ts tq-1: silhouette coverage, outline) does not apply;
// these checks keep the same spirit (crisp alpha, a small palette, readable contrast) for atlases. Pure.
import type { Raster } from "../textures/render";
import type { SkinLayout } from "./compile";
import { FACES } from "./spec";

export const SKIN_QUALITY_VERSION = "sk-1";
export type Verdict = "pass" | "warn" | "fail";
export type SkinCheck = { id: string; verdict: Verdict; value: number | string; note: string };
export type SkinQuality = { version: string; verdict: Verdict; checks: SkinCheck[] };

const lum = (r: number, g: number, b: number) => {
  const f = (v: number) => { const c = v / 255; return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
  return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
};

export function skinQuality(r: Raster, layout: SkinLayout): SkinQuality {
  const n = r.size;
  const used = new Uint8Array(n * n);
  let faceTexels = 0, holes = 0;
  for (const c of layout.cubes) for (const f of FACES) {
    const q = c.faces[f];
    for (let y = q.y; y < q.y + q.h; y++) for (let x = q.x; x < q.x + q.w; x++) {
      if (x < 0 || y < 0 || x >= n || y >= n) { holes++; continue; }
      used[y * n + x] = 1; faceTexels++;
      if (r.px[(y * n + x) * 4 + 3] !== 255) holes++;
    }
  }
  let semi = 0;
  const colours = new Set<number>();
  let lo = Infinity, hi = -Infinity;
  for (let i = 0; i < n * n; i++) {
    const a = r.px[i * 4 + 3];
    if (a !== 0 && a !== 255) semi++;
    if (!used[i] || a === 0) continue;
    const R = r.px[i * 4], G = r.px[i * 4 + 1], B = r.px[i * 4 + 2];
    colours.add((R << 16) | (G << 8) | B);
    const l = lum(R, G, B);
    lo = Math.min(lo, l); hi = Math.max(hi, l);
  }
  const contrast = Number.isFinite(lo) ? Math.round(((hi + 0.05) / (lo + 0.05)) * 100) / 100 : 0;
  const passPal = n >= 128 ? 96 : 64;
  const checks: SkinCheck[] = [
    { id: "coverage", verdict: holes ? "fail" : "pass", value: faceTexels ? Math.round(((faceTexels - holes) / faceTexels) * 1000) / 1000 : 0, note: "every texel a cube face uses is painted and fully opaque" },
    { id: "alpha", verdict: semi ? "fail" : "pass", value: semi, note: "no semi-transparent pixels (item displays render alpha poorly)" },
    { id: "palette_size", verdict: colours.size <= passPal ? "pass" : colours.size <= passPal * 2 ? "warn" : "fail", value: colours.size, note: `distinct colours on the used area (pass <= ${passPal})` },
    { id: "contrast", verdict: contrast >= 3 ? "pass" : contrast >= 2 ? "warn" : "fail", value: contrast, note: "darkest vs lightest shade (WCAG ratio): features must read at a distance" },
    { id: "atlas_use", verdict: "pass", value: Math.round((faceTexels / (n * n)) * 1000) / 1000, note: "share of the sheet the faces use (information)" },
  ];
  const verdict: Verdict = checks.some((c) => c.verdict === "fail") ? "fail" : checks.some((c) => c.verdict === "warn") ? "warn" : "pass";
  return { version: SKIN_QUALITY_VERSION, verdict, checks };
}

