package dev.nxeon.tf.sound;

import org.bukkit.Difficulty;
import org.bukkit.Location;
import org.bukkit.SoundCategory;
import org.bukkit.World;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntityType;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Cyrus R1 sound-slice Test Flight fixture: does exactly what the build prompt tells a generated mod to do for custom
 * sounds on a reskinned vanilla mob: spawn it, entity.setSilent(true), then world.playSound(location,
 * "<namespace>:<set>.<event>", SoundCategory.X, 1f, 1f) with the String-key overload. A flight proves the calls work
 * on the real Paper server; no client is connected, so nothing is heard and playback is NOT verified.
 */
public class SoundPlugin extends JavaPlugin {
    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length != 2) {
            sender.sendMessage("usage: /tfsound <namespace:key> <CATEGORY>");
            return true;
        }
        // each step reports where it failed (a flight has no client and no stack trace in the RCON answer)
        String step = "world";
        try {
            World world = getServer().getWorlds().get(0);
            Location loc = world.getSpawnLocation();
            // Paper 26.2 refuses to spawn a monster in Peaceful (IllegalStateException; 1.21.11 allows it): the flight
            // world is Peaceful, so switch to Easy first and say so
            String diff = world.getDifficulty().name();
            if (world.getDifficulty() == Difficulty.PEACEFUL) { world.setDifficulty(Difficulty.EASY); diff += "->EASY"; }
            step = "spawn";
            Entity mob = world.spawnEntity(loc, EntityType.ZOMBIE);
            step = "silence";
            mob.setSilent(true);
            step = "category";
            SoundCategory cat = SoundCategory.valueOf(args[1]);
            step = "playSound";
            world.playSound(mob.getLocation(), args[0], cat, 1.0f, 1.0f);
            sender.sendMessage("played=" + args[0] + " category=" + cat.name() + " silent=" + mob.isSilent() + " mob=" + mob.getType().name() + " difficulty=" + diff);
            mob.remove();
        } catch (Throwable t) {
            sender.sendMessage("error at " + step + ": " + t.getClass().getName() + ": " + t.getMessage());
        }
        return true;
    }
}

