// Cyrus R1: put a build's hosted resource pack in front of players on ONE server: make sure the managed Nxeon Pack
// Loader is there (ref-counted, lib/cyrus/managed) and upsert this mod's entry in plugins/NxeonPackLoader/packs.json
// (lib/cyrus/packhost/deliver.ts writes it atomically; the plugin reloads it by itself). Removal is the reverse.
//
// OFF behind the existing managed-plugin flag (CYRUS_MANAGED_PLUGINS_REAL=1): with it unset nothing here touches a
// server and the result says so. Turning that flag on (plus the R0 owner steps: migration, catalog seed, the Pack
// Loader jar on the worker host, pack storage) is the only switch. Runs in the worker after the Mods engine installed
// the mod's jar (worker/game-mods.ts), never in a request handler.
import type { GuestFs } from "../../mods/guest-fs";
import { MANAGED_REAL_FLAG } from "../managed/installer";
import { ensureManagedPlugin, releaseManagedPlugin, type ManagedDeps } from "../managed/service";
import { readLoaderConfig, writeLoaderConfig } from "../packhost/deliver";
import { applyPackChange } from "../packhost/loader-config";
import { PACK_ROLE, readBuildAssets } from "./sync";

export const PACK_LOADER_KEY = "nxeon-pack-loader";
export const PACK_DELIVERY_FLAG = MANAGED_REAL_FLAG;

export type DeliverBuild = { id: string; mcVersion: string; result: unknown };
export type DeliverDeps = { managed: ManagedDeps; fs: GuestFs; env?: Record<string, string | undefined>; base?: string };
export type DeliverResult =
  | { ok: true; action: "no_pack" | "switched_off" | "added" | "updated" | "unchanged" | "removed" | "absent"; wrote: boolean; loader?: string; notes: string[] }
  | { ok: false; error: string };

const dependentFor = (projectId: string) => `project:${projectId}`;

export async function deliverBuildPack(serverId: string, build: DeliverBuild, deps: DeliverDeps): Promise<DeliverResult> {
  const a = readBuildAssets(build.result);
  if (!a?.loader || a.status !== "ready") return { ok: true, action: "no_pack", wrote: false, notes: [] };
  if ((deps.env ?? process.env)[PACK_DELIVERY_FLAG] !== "1") {
    return { ok: true, action: "switched_off", wrote: false, notes: [`custom-texture pack delivery is switched off (${PACK_DELIVERY_FLAG} is not 1); the plugin was installed without it`] };
  }
  const loader = a.loader;
  const ens = await ensureManagedPlugin(deps.managed, { serverId, key: PACK_LOADER_KEY, mcVersion: build.mcVersion, dependent: dependentFor(a.projectId) });
  if (!ens.ok) return { ok: false, error: `Nxeon Pack Loader: ${ens.error}` };
  const cur = await readLoaderConfig(deps.fs, deps.base);
  if (!cur.ok) return { ok: false, error: `the server's pack config is invalid, so it was left alone: ${cur.error}` };
  const r = applyPackChange(cur.config, { op: "upsert", namespace: a.namespace, role: PACK_ROLE, sha1: loader.sha1, prompt: loader.prompt, required: loader.required }, {
    urlFor: (sha1) => { if (sha1 !== loader.sha1) throw new Error("pack url requested for another sha1"); return loader.url; },
  });
  if (!r.ok) return { ok: false, error: r.error };
  const wrote = r.changed ? await writeLoaderConfig(deps.fs, r.config, deps.base) : false;
  const notes = [...r.warnings.map((w) => w.message)];
  if (ens.action === "installed" || ens.action === "upgraded") notes.push("the Nxeon Pack Loader was installed; it starts with the next server restart");
  return { ok: true, action: r.action, wrote, loader: ens.action, notes };
}

