// BetterModel pack hand-off (Cyrus R3). BetterModel builds its OWN resource pack on the server at start (and on
// `/bettermodel reload`): `plugins/BetterModel/build.zip` (config pack-type zip, build-folder-location BetterModel/build,
// verified on Paper 26.2 with the pinned 3.5.0). Its item names are per model (`assets/bettermodel/items/b/<model key>_<bone>.json`)
// but its model files are numbered in load order (`models/b/a.json`, ...), so the pack belongs to the SERVER (every
// creature on it), not to one mod. Nxeon therefore:
//   1. reads build.zip from the server (GuestFs), checks it like any pack (zip check, pack.mcmeta, size cap, only
//      `assets/bettermodel/**` + pack.mcmeta/pack.png),
//   2. re-zips it deterministically (sorted entries, fixed timestamps): BetterModel writes the same CONTENT every start
//      but fresh zip timestamps (two real flights: identical CRCs, different zip sha), so without this every restart
//      would be a new sha1 and every player would re-download the pack,
//   3. publishes it content-addressed (packhost publishPack) and upserts ONE Pack Loader entry per server
//      (namespace nx_bmodel00, role "bettermodel"), next to each mod's own pack.
// Pure except the injected GuestFs/PackStore. OFF unless the caller is switched on (see deliver.ts).
import { inflateRawSync } from "node:zlib";
import type { GuestFs } from "../../mods/guest-fs";
import { readEntry, indexZip } from "../inventory/zipread";
import { inspectPackZip } from "../packhost/zipcheck";
import { publishPack } from "../packhost/publish";
import type { PackStore } from "../packhost/types";
import { applyPackChange, type LoaderConfig } from "../packhost/loader-config";
import { readLoaderConfig, writeLoaderConfig, MC_BASE } from "../packhost/deliver";
import { zip } from "../textures/zip";

/** Reserved pseudo-namespace for the server-level BetterModel pack entry (never a project namespace: not a hash). */
export const BETTERMODEL_PACK_NAMESPACE = "nx_bmodel00";
export const BETTERMODEL_PACK_ROLE = "bettermodel";
export const BETTERMODEL_BUILD_ZIP = "plugins/BetterModel/build.zip";
export const MAX_BETTERMODEL_PACK_BYTES = 32 * 1024 * 1024;
const ALLOWED = /^(pack\.mcmeta|pack\.png|assets\/bettermodel\/[a-z0-9_./-]+)$/;

export type Normalized = { ok: true; zip: Buffer; entries: number; bytes: number; contentSha256: string } | { ok: false; error: string };

/** Check BetterModel's build.zip and rewrite it deterministically (same content -> same bytes -> same sha1). */
export function normalizeBetterModelPack(buf: Buffer, opts: { maxBytes?: number } = {}): Normalized {
  const max = opts.maxBytes ?? MAX_BETTERMODEL_PACK_BYTES;
  if (buf.length > max) return { ok: false, error: `BetterModel's pack is ${buf.length} bytes; the limit is ${max}` };
  const chk = inspectPackZip(buf, { maxEntries: 20000 });
  if (!chk.ok) return { ok: false, error: `BetterModel's pack is not a valid resource pack: ${chk.error}` };
  let idx;
  try { idx = indexZip(buf); } catch (e) { return { ok: false, error: `unreadable zip: ${(e as Error).message}` }; }
  const files: { path: string; data: Buffer }[] = [];
  let total = 0;
  for (const e of idx.entries) {
    if (e.name.endsWith("/")) continue;
    if (!ALLOWED.test(e.name) || e.name.split("/").includes("..")) return { ok: false, error: `unexpected file in BetterModel's pack: ${e.name.slice(0, 120)}` };
    let data: Buffer;
    try { data = readEntry(buf, e, { maxBytes: max - total, inflate: (b, n) => inflateRawSync(b, { maxOutputLength: n }) }); } catch (err) { return { ok: false, error: `${e.name}: ${(err as Error).message}` }; }
    total += data.length;
    if (total > max) return { ok: false, error: "BetterModel's pack inflates past the size limit" };
    files.push({ path: e.name, data });
  }
  if (!files.some((f) => f.path === "pack.mcmeta")) return { ok: false, error: "BetterModel's pack has no pack.mcmeta" };
  const out = zip(files);
  const { createHash } = require("node:crypto") as typeof import("node:crypto");
  const h = createHash("sha256");
  for (const f of [...files].sort((a, b) => (a.path < b.path ? -1 : 1))) h.update(f.path).update("\0").update(createHash("sha256").update(f.data).digest());
  return { ok: true, zip: out, entries: files.length, bytes: out.length, contentSha256: h.digest("hex") };
}

export type HandoffResult =
  | { ok: true; action: "no_pack" | "added" | "updated" | "unchanged"; sha1?: string; url?: string; wrote: boolean; entries?: number }
  | { ok: false; error: string };

/**
 * After BetterModel (re)built its pack on a server: publish it and point the server's Pack Loader at it.
 * `prompt` is what players see in the accept dialog.
 */
export async function handoffBetterModelPack(deps: { fs: GuestFs; store: PackStore; maxBytes?: number; base?: string; prompt?: string; required?: boolean }): Promise<HandoffResult> {
  const base = deps.base ?? MC_BASE;
  const raw = await deps.fs.readFile(`${base}/${BETTERMODEL_BUILD_ZIP}`, (deps.maxBytes ?? MAX_BETTERMODEL_PACK_BYTES) + 1);
  if (!raw) return { ok: true, action: "no_pack", wrote: false };
  const n = normalizeBetterModelPack(raw, { maxBytes: deps.maxBytes });
  if (!n.ok) return n;
  const pub = await publishPack(deps.store, n.zip, { maxBytes: deps.maxBytes ?? MAX_BETTERMODEL_PACK_BYTES });
  if (!pub.ok) return { ok: false, error: `could not publish BetterModel's pack: ${pub.error}` };
  const cur = await readLoaderConfig(deps.fs, base);
  if (!cur.ok) return { ok: false, error: `the server's pack config is invalid, so it was left alone: ${cur.error}` };
  const r = applyPackChange(cur.config, {
    op: "upsert", namespace: BETTERMODEL_PACK_NAMESPACE, role: BETTERMODEL_PACK_ROLE, sha1: pub.sha1,
    prompt: deps.prompt ?? "This server uses animated custom creatures. Accept the pack to see them.", required: deps.required ?? false, owner: "bettermodel",
  }, { urlFor: () => pub.url });
  if (!r.ok) return { ok: false, error: r.error };
  const wrote = r.changed ? await writeLoaderConfig(deps.fs, r.config as LoaderConfig, base) : false;
  return { ok: true, action: r.action as "added" | "updated" | "unchanged", sha1: pub.sha1, url: pub.url, wrote, entries: n.entries };
}

