/** The plan-gate kind of a build asset kind (lib/cyrus/engine-core/asset-gate.ts): a creature is a model asset. */
export const GATE_KIND: Readonly<Record<BuildAssetKind, "texture" | "sound" | "model">> = { texture: "texture", sound: "sound", creature: "model" };
/** What a creature request on a version without animated creatures gets instead (owner wording, R3). */
export const CREATURE_DOWNGRADE = "Animated custom creatures need Minecraft 26.x; on this version Cyrus can build the plugin with custom sounds (and a static item-style model later), on a vanilla-looking mob.";''')
s=s.replace('''const FALLBACK: Record<BuildAssetKind, string> = { texture: "vanilla item looks", sound: "vanilla sounds" };
const WORD: Record<BuildAssetKind, string> = { texture: "Custom textures", sound: "Custom sounds" };''','''const FALLBACK: Record<BuildAssetKind, string> = { texture: "vanilla item looks", sound: "vanilla sounds", creature: "a vanilla-looking mob" };
