    if (!/setInvisible\s*\(\s*true\s*\)/.test(text)) soft.push("The base mob must be invisible: call setInvisible(true) on it (BetterModel draws the creature).");
    if (pluginYml != null && !/^\s*depend\s*:.*\bBetterModel\b/m.test(pluginYml) && !/^\s*depend\s*:\s*\n(\s*-\s*\S+\s*\n)*\s*-\s*BetterModel\b/m.test(pluginYml)) soft.push("plugin.yml must declare depend: [BetterModel] (the Nxeon-managed engine that draws the creatures).");
  }
  for (const r of results) { r.ok = r.problems.length === 0; problems.push(...r.problems); }
  return { files, results, problems: [...new Set(problems)], soft: [...new Set(soft)].slice(0, 30) };
}

