});

describe("build service: section, parser, workspace checks", () => {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const TX = require(path.join(ROOT, "services/modbuilder/textures.js"));
