    for (const w of ["assets/creatures/<name>.json", "BetterModel.model(\"<namespace>_<name>\")", "setSilent(true)", "setInvisible(true)", "depend: [BetterModel]", "tracker.close()", "Bedrock"]) assert.ok(P.CREATURE_SECTION.includes(w), w);
    assert.equal(P.assetsBlock({ texture: true, sound: false, namespace: NS }), P.assetsBlock({ texture: true, sound: false, namespace: NS, creature: false }));
    assert.match(P.assetsBlock({ texture: false, sound: true, creature: true, namespace: NS }), /BetterModel\.model\("nx_r6cr34tr_<name>"\)/);
  });
  it("parser: creature only on creature versions with the API installed; absent field = byte-identical", () => {
    const IM = new Set(["1.21.11", "26.2"]);
