// creature delivery (memory installer + local fake guest), the service section/parser/workspace checks, page lines.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { checkRigSpec, rigSpecJsonSchema, MAX_BONES, type RigSpec } from "../lib/cyrus/creature/spec";
import { compileCreature, layoutSkin, stableUuid, bbBoneName } from "../lib/cyrus/creature/compile";
