const ROOT = path.resolve(__dirname, "..");
const FX = path.join(ROOT, "test/fixtures/cyrus-creatures");
const NS = "nx_r6cr34tr";
const load = (n: string) => JSON.parse(fs.readFileSync(path.join(FX, `${n}.json`), "utf8"));
const FIXTURES = ["banshee", "ghoul", "dire_wolf"];
// eslint-disable-next-line @typescript-eslint/no-require-imports
const CSJS = require(path.join(ROOT, "services/modbuilder/creature-spec.js"));
const ok = (raw: unknown, ns = NS) => { const c = checkRigSpec(raw, { namespace: ns }); if (!c.ok) throw new Error(c.error); return c; };
const clone = <T>(v: T): T => JSON.parse(JSON.stringify(v));

/** A small explicit-form spec (one root + one child) used for negative cases. */
function explicitSpec(): Record<string, unknown> {
  const clip = (loop: boolean) => ({ length: 1, loop, tracks: [{ bone: "body", channel: "rotation", wave: { amp: [5, 0, 0] } }] });
  return {
    version: 1, name: "blob", archetype: "flyer", hitbox: { width: 0.6, height: 0.6 }, baseEntity: "VEX",
    skin: { palette: { a: "#335577", b: "#ddeeff" } },
    bones: [
      { name: "body", parent: null, pivot: [0, 4, 0], cubes: [{ from: [-3, 0, -3], to: [3, 6, 3], material: "a", decals: { north: [{ op: "rect", x: 1, y: 1, w: 2, h: 1, c: "b" }] } }] },
      { name: "wing", parent: "body", pivot: [3, 5, 0], cubes: [{ from: [3, 4, -1], to: [9, 5, 1], material: "b" }] },
    ],
    animations: { idle: clip(true), walk: clip(true), attack: clip(false), hurt: clip(false), death: clip(false) },
    sounds: { hurt: `${NS}:blob.hurt` },
  };
}

describe("RigSpec v1 validation", () => {
  it("accepts the three template fixtures and expands them to explicit, self-validating specs", () => {
    for (const n of FIXTURES) {
      const c = ok(load(n));
      assert.ok(c.spec.bones.length >= 9 && c.spec.bones.length <= MAX_BONES, n);
      for (const clip of ["idle", "walk", "attack", "hurt", "death"]) assert.ok(c.spec.animations[clip], `${n} ${clip}`);
      assert.equal((c.spec as unknown as { template?: unknown }).template, undefined);
      const again = ok(clone(c.spec));
      assert.deepEqual(again.spec, c.spec, `${n}: the expanded spec validates to itself`);
    }
  });
  it("every template feature compiles", () => {
    for (const [arch, base] of [["floating_ghost", "banshee"], ["humanoid", "ghoul"], ["quadruped", "dire_wolf"]] as const) {
      const feats = { floating_ghost: ["hood", "crown", "claws"], humanoid: ["horns", "hood", "cape"], quadruped: ["horns", "mane", "spikes"] }[arch];
      for (const h of [0.7, 1, 1.5]) {
        const s = load(base); s.template = { features: feats, height: h };
        const c = ok(s);
        const r = compileCreature(c.spec, NS);
        assert.ok(r.ok, `${arch} ${h}: ${!r.ok && r.error}`);
      }
    }
  });
  const bad: [string, (s: Record<string, unknown>) => void, RegExp][] = [
    ["unknown key", (s) => { s.extra = 1; }, /extra|Unrecognized/i],
    ["template + bones", (s) => { s.template = {}; }, /either template or bones/],
    ["missing clip", (s) => { delete (s.animations as Record<string, unknown>).death; }, /missing the death clip/],
    ["death loops", (s) => { (s.animations as Record<string, { loop: boolean }>).death.loop = true; }, /death plays once/],
    ["idle does not loop", (s) => { (s.animations as Record<string, { loop: boolean }>).idle.loop = false; }, /idle must loop/],
    ["duplicate bone", (s) => { (s.bones as Record<string, unknown>[])[1].name = "body"; }, /duplicate bone/],
    ["two roots", (s) => { (s.bones as Record<string, unknown>[])[1].parent = null; }, /exactly one root/],
    ["unknown parent", (s) => { (s.bones as Record<string, unknown>[])[1].parent = "nope"; }, /unknown parent/],
    ["cycle", (s) => { (s.bones as Record<string, unknown>[])[0].parent = "wing"; }, /root|cycle/],
    ["decal outside its face", (s) => { ((s.bones as { cubes: { decals: { north: { x: number }[] } }[] }[])[0].cubes[0].decals.north[0]).x = 5; }, /outside the north face/],
    ["unknown colour", (s) => { (s.bones as { cubes: { material: string }[] }[])[1].cubes[0].material = "zz"; }, /unknown palette colour zz/],
    ["flat cube", (s) => { (s.bones as { cubes: { to: number[] }[] }[])[1].cubes[0].to = [9, 4.1, 1]; }, /at least 0.2 units/],
    ["foreign sound namespace", (s) => { s.sounds = { hurt: "nx_zzzzzzzz:blob.hurt" }; }, /reserved namespace is nx_r6cr34tr/],
    ["bad sound key", (s) => { s.sounds = { hurt: "minecraft:entity.zombie.hurt" }; }, /sound keys are/],
    ["track on a missing bone", (s) => { (s.animations as Record<string, { tracks: { bone: string }[] }>).idle.tracks[0].bone = "tail"; }, /unknown bone tail/],
    ["wave and keys", (s) => { (s.animations as Record<string, { tracks: Record<string, unknown>[] }>).idle.tracks[0].keys = [{ t: 0, v: [0, 0, 0] }, { t: 1, v: [0, 0, 0] }]; }, /exactly one of wave or keys/],
    ["keys not 0..1", (s) => { (s.animations as Record<string, { tracks: Record<string, unknown>[] }>).attack.tracks[0] = { bone: "body", channel: "rotation", keys: [{ t: 0.1, v: [0, 0, 0] }, { t: 1, v: [9, 0, 0] }] }; }, /start at t 0/],
    ["loop not closed", (s) => { (s.animations as Record<string, { tracks: Record<string, unknown>[] }>).idle.tracks[0] = { bone: "body", channel: "rotation", keys: [{ t: 0, v: [0, 0, 0] }, { t: 1, v: [9, 0, 0] }] }; }, /end where it starts/],
    ["too many bones", (s) => { s.bones = [...(s.bones as unknown[]), ...Array.from({ length: 33 }, (_, i) => ({ name: `b${i}`, parent: "body", pivot: [0, 0, 0], cubes: [] }))]; }, /32|too_big|Too big/i],
    ["no template for flyer", (s) => { delete s.bones; delete s.animations; s.template = {}; }, /no template for flyer/],
  ];
  for (const [label, mut, re] of bad) it(`rejects: ${label}`, () => {
    const s = explicitSpec(); mut(s);
    const c = checkRigSpec(s, { namespace: NS });
    assert.equal(c.ok, false);
    if (!c.ok) assert.match(c.errors.map((e) => `${e.path}: ${e.message}`).join(" | "), re);
  });
  it("template errors: unknown feature, missing palette key", () => {
    const s = load("banshee"); s.template.features = ["wings"];
    assert.match((checkRigSpec(s) as { error: string }).error, /unknown feature wings/);
    const t = load("banshee"); delete t.skin.palette.mouth;
    assert.match((checkRigSpec(t) as { error: string }).error, /needs the colour "mouth"/);
  });
  it("warnings never block: mismatched hitbox, missing sounds", () => {
    const s = load("banshee"); s.hitbox.height = 4; s.sounds = {};
    const c = ok(s);
    assert.ok(c.warnings.some((w) => /hitbox height/.test(w)));
    assert.ok(c.warnings.some((w) => /no attack sound/.test(w)));
  });
});

