describe("compiler", () => {
  // Golden hashes (compiler rig-c1, bbmodel format 5.0). A change here changes every shipped model: bump COMPILER_VERSION.
  const GOLDEN: Record<string, { bbmodel: string; png: string }> = JSON.parse(fs.readFileSync(path.join(FX, "golden.json"), "utf8"));
  for (const n of FIXTURES) it(`${n}: golden hashes, deterministic`, () => {
    const s = ok(load(n)).spec;
    const a = compileCreature(s, NS), b = compileCreature(clone(s), NS);
    assert.ok(a.ok && b.ok);
    if (!a.ok || !b.ok) return;
    assert.equal(a.creature.bbmodel, b.creature.bbmodel);
    assert.ok(a.creature.png.equals(b.creature.png));
    assert.equal(a.creature.bbmodelSha256, GOLDEN[n].bbmodel, `${n} bbmodel`);
    assert.equal(a.creature.pngSha256, GOLDEN[n].png, `${n} png`);
  });
  it("a different namespace gives different UUIDs (no collisions across mods)", () => {
    const s = ok(load("banshee")).spec;
    const a = compileCreature(s, NS), b = compileCreature(s, "nx_00000001");
    assert.ok(a.ok && b.ok && a.creature.bbmodelSha256 !== b.creature.bbmodelSha256);
  });
  it("the .bbmodel has the structure BetterModel 3.5.0 loaded on Paper 26.2", () => {
    const s = ok(load("banshee")).spec;
    const r = compileCreature(s, NS);
    assert.ok(r.ok); if (!r.ok) return;
    const m = JSON.parse(r.creature.bbmodel);
    assert.deepEqual(m.meta, { format_version: "5.0", model_format: "free", box_uv: false });
    assert.equal(m.name, `${NS}_banshee`);
    assert.equal(m.groups.length, s.bones.length);
    assert.equal(m.elements.length, s.bones.reduce((a: number, b) => a + b.cubes.length, 0));
    const names = m.groups.map((g: { name: string }) => g.name);
    assert.ok(names.includes("hi_head") && names.includes("glow_eyes"));
    const uuids = [...m.groups, ...m.elements].map((x: { uuid: string }) => x.uuid);
    assert.equal(new Set(uuids).size, uuids.length);
    for (const u of uuids) assert.match(u, /^[0-9a-f]{8}-[0-9a-f]{4}-5[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
    // every element appears exactly once in the outliner tree
    const seen: string[] = [];
    const walk = (n: { children: unknown[] }) => { for (const c of n.children) { if (typeof c === "string") seen.push(c); else walk(c as { children: unknown[] }); } };
    walk(m.outliner[0]);
    assert.deepEqual([...seen].sort(), m.elements.map((e: { uuid: string }) => e.uuid).sort());
    for (const e of m.elements) for (const f of Object.values(e.faces) as { uv: number[] }[]) assert.ok(f.uv.every((v) => v >= 0 && v <= m.resolution.width));
    const loops = Object.fromEntries(m.animations.map((a: { name: string; loop: string }) => [a.name, a.loop]));
    assert.deepEqual(loops, { idle: "loop", walk: "loop", attack: "once", hurt: "once", death: "hold" });
    assert.match(m.textures[0].source, /^data:image\/png;base64,iVBOR/);
    // a looping wave ends exactly where it starts
    const idle = m.animations.find((a: { name: string }) => a.name === "idle");
    for (const an of Object.values(idle.animators) as { keyframes: { time: number; channel: string; data_points: unknown[] }[] }[]) {
      for (const ch of ["rotation", "position", "scale"]) {
        const ks = an.keyframes.filter((k) => k.channel === ch).sort((a, b) => a.time - b.time);
        if (ks.length) assert.deepEqual(ks[0].data_points, ks[ks.length - 1].data_points);
      }
    }
    assert.equal(bbBoneName({ name: "x", tag: "none" } as RigSpec["bones"][number]), "x");
  });
  it("stable UUIDs are RFC 4122 shaped and seed-dependent", () => {
    assert.notEqual(stableUuid("a"), stableUuid("b"));
    assert.equal(stableUuid("a"), stableUuid("a"));
  });
  it("skin layout: 64 px when it fits, 128 px when needed, an error when nothing fits", () => {
    const s = ok(load("banshee")).spec;
    const l = layoutSkin(s); assert.ok(l.ok && l.layout.size === 64);
    const big = ok(explicitSpec()).spec;
    big.bones[0].cubes = Array.from({ length: 6 }, () => ({ from: [-8, 0, -8], to: [8, 16, 8], material: "a", shade: "solid", inflate: 0 } as RigSpec["bones"][number]["cubes"][number]));
    const l2 = layoutSkin(big); assert.ok(l2.ok && l2.layout.size === 128);
    big.bones[0].cubes = Array.from({ length: 12 }, () => ({ from: [-12, 0, -12], to: [12, 24, 12], material: "a", shade: "solid", inflate: 0 } as RigSpec["bones"][number]["cubes"][number]));
    const l3 = layoutSkin(big); assert.equal(l3.ok, false);
  });
  it("skin quality passes on every template and fails a transparent hole", () => {
    for (const n of FIXTURES) {
      const r = compileCreature(ok(load(n)).spec, NS);
      assert.ok(r.ok); if (!r.ok) continue;
      assert.equal(skinQuality(r.creature.raster, r.creature.layout).verdict, "pass", n);
      const holed = { size: r.creature.raster.size, px: r.creature.raster.px.slice() };
      const f = r.creature.layout.cubes[0].faces.north;
      holed.px[(f.y * holed.size + f.x) * 4 + 3] = 0;
      assert.equal(skinQuality(holed, r.creature.layout).verdict, "fail");
    }
  });
  it("the preview renderer draws a contact sheet (deterministic PNG)", () => {
    const s = ok(load("dire_wolf")).spec;
    const r = compileCreature(s, NS); assert.ok(r.ok); if (!r.ok) return;
    const a = previewSheet(s, r.creature.layout, r.creature.raster, { cell: 64 });
    const b = previewSheet(s, r.creature.layout, r.creature.raster, { cell: 64 });
    assert.ok(a.png.equals(b.png));
    let painted = 0; for (let i = 3; i < a.raster.px.length; i += 4) if (a.raster.px[i - 1] !== 56 && a.raster.px[i - 1] !== 50) painted++;
    assert.ok(painted > 500, "something was drawn");
  });
  it("portal re-check: drops invalid specs with a reason, accepts and compiles good ones", () => {
    const r = checkReturnedCreatures([{ name: "banshee", spec: load("banshee") }, { name: "nope", spec: { version: 1 } }, { name: "ghoul", spec: load("banshee") }], NS);
    assert.deepEqual(r.ok.map((c) => c.name), ["banshee"]);
    assert.equal(r.dropped.length, 2);
    assert.match(r.dropped[1].reason, /does not match ghoul/);
  });
});

describe("plan gate (model kind), version, router", () => {
  const plans = ["free", "katara", "saka", "all", "yakko", null, "garbage"];
  it("creatures: top plan only, 26.x only, buildable only, switched on only", () => {
    const row = getVersion("26.2")!;
    const was = row.buildable;
    try {
      row.buildable = true; // the registry override pattern: 26.2 is preview (not buildable) in the shipped registry
      for (const plan of plans) {
        const p = planBuildAssets({ plan, requested: ["creature", "sound"], mcVersion: "26.2", creaturesOn: true });
        const top = plan === "all" || plan === "yakko";
        assert.equal(p.allowed.creature, top, `${plan}`);
        assert.equal(p.allowed.sound, top || plan === "saka", `${plan} sound`);
        if (!top) assert.ok(p.decisions.find((d) => d.kind === "creature")!.code !== "allowed");
      }
      const off = planBuildAssets({ plan: "all", requested: ["creature"], mcVersion: "26.2", creaturesOn: false });
      assert.equal(off.allowed.creature, false);
      assert.match(off.notices[0], /not switched on/);
      // keeping / installing is never gated: a change on a lower plan keeps the creature and says so
      const keep = planBuildAssets({ plan: "saka", requested: ["creature"], mcVersion: "26.2", change: true, existing: ["creature"], creaturesOn: true });
      assert.match(keep.notices[0], /kept exactly as they are/);
    } finally { row.buildable = was; }
    const notBuildable = planBuildAssets({ plan: "all", requested: ["creature"], mcVersion: "26.2", creaturesOn: true });
    assert.equal(notBuildable.allowed.creature, false);
    assert.match(notBuildable.notices[0], /not buildable yet/);
  });
  it("1.21.x downgrades with the owner's wording and still builds the sounds", () => {
    for (const v of ["1.21.1", "1.21.4", "1.21.8", "1.21.11"]) {
      const p = planBuildAssets({ plan: "all", requested: requestedAssetKinds({ explicit: ["creature"] }), mcVersion: v, creaturesOn: true });
      assert.equal(p.allowed.creature, false);
      assert.equal(p.allowed.sound, true, "custom sounds on this version");
      const d = p.decisions.find((x) => x.kind === "creature")!;
      assert.equal(d.code, "version");
      assert.ok(d.reason!.startsWith(CREATURE_DOWNGRADE));
    }
    assert.deepEqual(requestedAssetKinds({ text: "add animated creatures that haunt the swamp" }), ["sound", "creature"]);
  });
  it("router: entity_model is a downgrade (warn) on 1.21.x, info on 26.x, never a client mod claim", () => {
    const adapter = getAdapter("minecraft")!;
    const spec = (version: string) => ({ schemaVersion: 1, game: "minecraft", target: { version }, namespace: NS, summary: "A banshee mob with animated custom creatures and sounds", routes: ["plugin"], requirements: [{ id: "REQ-1", text: "Add animated creatures", priority: "must" }], install: { side: "server", restartRequired: true } });
    const r1 = routeSpec(spec("1.21.11") as never, adapter);
    const lim = r1.limits.find((l) => l.id === "entity_model:version")!;
    assert.equal(lim.severity, "warn");
    assert.match(lim.message, /need Minecraft 26\.x; on 1\.21\.11 Cyrus builds the plugin with custom sounds/);
    const r2 = routeSpec(spec("26.2") as never, adapter);
    assert.ok(!r2.limits.some((l) => l.id === "entity_model:version"));
    assert.equal(r2.limits.find((l) => l.id === "entity_model")!.severity, "info");
    assert.match(r2.limits.find((l) => l.id === "entity_model")!.message, /Nxeon-managed BetterModel/);
  });
  it("build request: creature only rides along when allowed; requested-but-refused stays out of the service call", async () => {
    const row = getVersion("26.2")!; const was = row.buildable;
    const deps = (tier: string, on: boolean) => ({ tierOf: async () => tier, projectForRootBuild: async () => ({ id: "cp1", namespace: NS }), createProject: async () => ({ id: "cp1", namespace: NS }), soundLibraryCleared: () => false, creaturesEnabled: () => on });
    try {
      row.buildable = true;
      const a = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, explicit: ["creature"], text: "", mcVersion: "26.2" }, deps("all", true));
      assert.deepEqual(a.service, { texture: false, sound: true, namespace: NS, library: false, creature: true });
      const b = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, explicit: ["creature"], text: "", mcVersion: "26.2" }, deps("all", false));
      assert.equal(b.service?.creature, undefined);
      const c = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, explicit: ["texture"], text: "", mcVersion: "26.2" }, deps("all", true));
      assert.deepEqual(c.service, { texture: true, sound: false, namespace: NS }, "texture-only stays byte-identical");
    } finally { row.buildable = was; }
  });
});

