describe("BetterModel pack hand-off", () => {
  const real = fs.readFileSync(path.join(FX, "bettermodel-build.zip")); // collected from a real Paper 26.2 flight
  it("normalises BetterModel's build.zip deterministically (timestamps do not change the bytes)", () => {
    const a = normalizeBetterModelPack(real);
    assert.ok(a.ok); if (!a.ok) return;
    assert.equal(a.entries, 26);
    // re-zip the same content with other timestamps: same normalised bytes
    const b = normalizeBetterModelPack(Buffer.from(a.zip));
    assert.ok(b.ok && b.zip.equals(a.zip) && b.contentSha256 === a.contentSha256);
  });
  it("refuses files outside assets/bettermodel and non-packs", () => {
    const bad = zip([{ path: "pack.mcmeta", data: Buffer.from("{}") }, { path: "assets/minecraft/textures/x.png", data: Buffer.from("x") }]);
    assert.match((normalizeBetterModelPack(bad) as { error: string }).error, /unexpected file/);
    assert.equal(normalizeBetterModelPack(Buffer.from("nope")).ok, false);
    assert.match((normalizeBetterModelPack(real, { maxBytes: 100 }) as { error: string }).error, /limit/);
  });
  it("publishes it and upserts ONE server-level Pack Loader entry; idempotent", async () => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), "cr-hand-"));
    try {
      const gfs = new LocalGuestFs(path.join(root, "guest"));
      const store = new LocalDiskStore(path.join(root, "store"), "https://packs.example.invalid");
      assert.deepEqual(await handoffBetterModelPack({ fs: gfs, store }), { ok: true, action: "no_pack", wrote: false });
      await gfs.writeFile("/opt/mc/plugins/BetterModel/build.zip", real);
      const a = await handoffBetterModelPack({ fs: gfs, store });
      assert.ok(a.ok && a.action === "added" && a.wrote);
      const b = await handoffBetterModelPack({ fs: gfs, store });
      assert.ok(b.ok && b.action === "unchanged" && !b.wrote && b.ok && a.ok && b.sha1 === a.sha1);
      const cfg = await readLoaderConfig(gfs);
      assert.ok(cfg.ok && cfg.config!.packs.length === 1 && cfg.config!.packs[0].role === "bettermodel" && cfg.config!.packs[0].owner === "bettermodel");
      assert.equal(BETTERMODEL_PACK_NAMESPACE, "nx_bmodel00");
    } finally { fs.rmSync(root, { recursive: true, force: true }); }
  });
});

