      if (a.ok) assert.deepEqual(a.wrote, ["plugins/BetterModel/config.yml", `plugins/BetterModel/models/${NS}_banshee.bbmodel`]);
      const b = await deliverCreatures({ serverId: "s", mcVersion: "26.2", namespace: NS, projectId: "p", creatures: stored() }, deps);
      assert.ok(b.ok && b.wrote.length === 0 && !b.restartRequired, JSON.stringify(b));
      // an owner-edited config is left alone
      await gfs.writeFile("/opt/mc/plugins/BetterModel/config.yml", Buffer.from("metrics: true\n"));
      const c = await deliverCreatures({ serverId: "s", mcVersion: "26.2", namespace: NS, projectId: "p", creatures: stored() }, deps);
      assert.ok(c.ok && c.notes.some((n) => /left it as it is/.test(n)));
      // tampered spec: refused before anything is written
      const t = stored(); t[0].bbmodelSha256 = "0".repeat(64);
      const d = await deliverCreatures({ serverId: "s", mcVersion: "26.2", namespace: NS, projectId: "p", creatures: t }, deps);
      assert.equal(d.ok, false);
      const e = await removeCreatures({ serverId: "s", mcVersion: "26.2", namespace: NS, projectId: "p" }, deps);
      assert.ok(e.ok && e.action === "removed");
      assert.equal(fs.existsSync(path.join(root, "opt/mc/plugins/BetterModel/models", `${NS}_banshee.bbmodel`)), false);
      const f = await deliverCreatures({ serverId: "s2", mcVersion: "1.21.11", namespace: NS, projectId: "p", creatures: stored() }, { ...deps, managed: managed(new Map()) });
      assert.equal(f.ok, false); if (!f.ok) assert.match(f.error, /no pinned version for Minecraft 1\.21/);
    } finally { fs.rmSync(root, { recursive: true, force: true }); }
  });
});

describe("build service: section, parser, workspace checks", () => {
