  const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const TX = require(path.join(ROOT, "services/modbuilder/textures.js"));
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const CR = require(path.join(ROOT, "services/modbuilder/creatures.js"));
  it("the section is absent unless creatures are allowed (prompt byte-identical) and present otherwise", () => {
    assert.equal(P.systemPrompt("26.2", { sound: true }), P.systemPrompt("26.2", { sound: true, creature: false }));
    const s = P.systemPrompt("26.2", { sound: true, creature: true });
    assert.ok(s.endsWith(P.CREATURE_SECTION));
    for (const w of ["assets/creatures/<name>.json", "BetterModel.model(\"<namespace>_<name>\")", "setSilent(true)", "setInvisible(true)", "depend: [BetterModel]", "tracker.close()", "Bedrock"]) assert.ok(P.CREATURE_SECTION.includes(w), w);
    assert.equal(P.assetsBlock({ texture: true, sound: false, namespace: NS }), P.assetsBlock({ texture: true, sound: false, namespace: NS, creature: false }));
    assert.match(P.assetsBlock({ texture: false, sound: true, creature: true, namespace: NS }), /BetterModel\.model\("nx_r6cr34tr_<name>"\)/);
  });
  it("parser: creature only on creature versions with the API installed; absent field = byte-identical", () => {
    const IM = new Set(["1.21.11", "26.2"]);
    assert.equal("creature" in TX.parseAssetsRequest({ sound: true, namespace: NS }, "26.2", IM, new Set(["26.2"]), () => true), false);
    assert.equal(TX.parseAssetsRequest({ creature: true, namespace: NS }, "26.2", IM, new Set(["26.2"]), () => true).creature, true);
    const off = TX.parseAssetsRequest({ creature: true, namespace: NS }, "1.21.11", IM, new Set(["26.2"]), () => true);
    assert.equal(off.creature, false); assert.match(off.notes.join(), /no animated creature support/);
    assert.equal(TX.parseAssetsRequest({ creature: true, namespace: NS }, "26.2", IM, new Set(["26.2"]), () => false).creature, false);
    assert.match(TX.parseAssetsRequest({ creature: "yes", namespace: NS }, "26.2", IM).error, /assets.creature/);
  });
  it("workspace check: hard problems and the soft plugin cross-checks", () => {
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "cr-ws-"));
    try {
      const w = (rel: string, t: string) => { fs.mkdirSync(path.dirname(path.join(ws, rel)), { recursive: true }); fs.writeFileSync(path.join(ws, rel), t); return { rel, abs: path.join(ws, rel) }; };
      w("assets/creatures/banshee.json", JSON.stringify(load("banshee")));
      w("assets/creatures/wrong.json", JSON.stringify(load("ghoul")));
      const j = w("src/main/java/x/B.java", "class B {}");
      const r = CR.checkWorkspaceCreatures(ws, { namespace: NS, javaFiles: [j], pluginYml: "name: B\n" });
      assert.ok(r.problems.some((p: string) => /"name" is "ghoul" but the file is wrong.json/.test(p)));
      for (const re of [/never attaches a model/, /model key "nx_r6cr34tr_banshee"/, /setSilent/, /setInvisible/, /depend: \[BetterModel\]/, /banshee.attack/]) assert.ok(r.soft.some((s: string) => re.test(s)), String(re));
      fs.rmSync(path.join(ws, "assets/creatures/wrong.json"));
      const k = w("src/main/java/x/B.java", `class B { void f(){ var t = BetterModel.model("${NS}_banshee"); m.setSilent(true); m.setInvisible(true); w.playSound(l, "${NS}:banshee.ambient", c, 1f, 1f); w.playSound(l, "${NS}:banshee.hurt", c, 1f, 1f); w.playSound(l, "${NS}:banshee.death", c, 1f, 1f); w.playSound(l, "${NS}:banshee.attack", c, 1f, 1f); } }`);
      const r2 = CR.checkWorkspaceCreatures(ws, { namespace: NS, javaFiles: [k], pluginYml: "name: B\ndepend: [BetterModel]\n" });
      assert.deepEqual(r2.problems, []); assert.deepEqual(r2.soft, []);
      assert.equal(r2.results[0].ok, true); assert.match(r2.results[0].sha256, /^[0-9a-f]{64}$/);
    } finally { fs.rmSync(ws, { recursive: true, force: true }); }
  });
});

describe("NxLabs page lines", () => {
  it("say only what is true", () => {
