// Cyrus R3 creature pipeline through the REAL services/modbuilder/server.js, offline: the Claude CLI, javac and jar are
// fakes (nothing is spent, no JDK). 26.2 is made buildable by a TEST-ONLY registry copy (MB_REGISTRY; the shipped
// registry says preview) and the BetterModel API jars are stand-ins listed in a test deps manifest (MB_DEPS_MANIFEST,
// sha256-verified like the real ones). Checks: the CREATURES section + namespace line, the RigSpec returned in
// assetResult.creatures, the BetterModel API jars on the javac classpath, one bounded asset repair for an invalid spec,
// creatures switched off on 1.21.11 (section absent, file removed), /health, and requests without creatures unchanged.
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, type ChildProcess } from "node:child_process";

const ROOT = path.resolve(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
const KEY = "test-key-creature-0123456789";
const NS = "nx_cr34tur3";

const FAKE_CLAUDE = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2);
