    assert.match(jc.cp, /bettermodel-api-3\.5\.0\.jar/); assert.match(jc.cp, /bettermodel-bukkit-api-3\.5\.0\.jar/);
    assert.equal(r.dedupeKey, null, "asset builds are never deduped");
  });

  it("an invalid RigSpec gets one asset repair, then ships fixed", async () => {
    const before = log().length;
    await api("POST", "/builds", { id: "cre-bad-02", prompt: "A banshee CREATUREBAD", mcVersion: "26.2", assets: { creature: true, namespace: NS } });
    const r = await waitDone("cre-bad-02");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events));
    const calls = log().slice(before);
    assert.equal(calls.length, 2); assert.equal(calls[1].repair, true);
    assert.ok(r.events.some((e: { message: string }) => /Creature check found/.test(e.message)));
    assert.equal(r.assetResult.creatures.length, 1);
  });

  it("1.21.11: creatures are switched off by the service (section absent, the file removed)", async () => {
    await api("POST", "/builds", { id: "cre-old-03", prompt: "A banshee CREATURE", mcVersion: "1.21.11", assets: { creature: true, namespace: NS } });
    const r = await waitDone("cre-old-03");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events));
    assert.equal(log().at(-1).creatures, false);
    assert.ok(!r.assetResult || !(r.assetResult.creatures ?? []).length);
    const src = await (await fetch(`http://127.0.0.1:${port}/builds/cre-old-03/source?path=assets/creatures/banshee.json`, { headers: { Authorization: `Bearer ${KEY}` } }));
    assert.notEqual(src.status, 200);
    assert.ok(!javacLog().at(-1).cp.includes("bettermodel"), "no BetterModel API without creatures");
  });
});

