// REAL Test Flights of the Cyrus R3 creature pipeline ON node-2 (not part of the unit suite: boots real Paper 26.2).
//   scripts/devhost run -- npx tsx test/cyrus-creature-real.ts [load|packloader|malformed|perf|all] [--out results.json]
// SERVER SIDE ONLY: no Minecraft client connects, so how the creatures LOOK and ANIMATE for a player, the resource
// pack download and the accept prompt are NOT verified. No AI model is used (the RigSpecs are the golden fixtures).
// What runs: the PRODUCTION code paths (portal re-check + compile = lib/cyrus/creature/portal.ts, the server delivery
// = deliverCreatures with the Nxeon-managed config, onto a staging dir that becomes the flight's
// plugins/BetterModel/models seed, the pack hand-off = handoffBetterModelPack) around a real server with the pinned
// BetterModel 3.5.0 jar and the TfCreature fixture (services/modbuilder/tools/testflight/fixtures/creature, compiled
// with javac --release 25 against the real 26.2 classpath + the allowlisted BetterModel API jars).
// Flights run one at a time (Test Flight lock; "busy" -> retry with backoff).
import { createHash } from "node:crypto";
import { execFileSync, spawn } from "node:child_process";
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { pullCollected, runTestFlight, type Remote, type RunResult } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";
import { checkReturnedCreatures } from "../lib/cyrus/creature/portal";
import { deliverCreatures, managedConfigTemplate } from "../lib/cyrus/creature/deliver";
import { handoffBetterModelPack, normalizeBetterModelPack } from "../lib/cyrus/creature/handoff";
import { loadCatalog } from "../lib/cyrus/managed/catalog";
import { memoryInstaller } from "../lib/cyrus/managed/installer";
import { LocalGuestFs } from "../lib/mods/guest-fs";
import { LocalDiskStore } from "../lib/cyrus/packhost/local";
import { serializeLoaderConfig, LOADER_CONFIG_PATH } from "../lib/cyrus/packhost/loader-config";
import { readLoaderConfig } from "../lib/cyrus/packhost/deliver";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const WORK = `${T}/cyrus-r6-creature-real`;
const NS = "nx_r6cr34tr";
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {});
    child.stdin.end(opts.input ?? undefined);
  }),
};

async function fly(spec: TestFlightSpec, label: string): Promise<RunResult> {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

const rconEv = (r: RunResult) => r.report.checks.find((c) => c.id === "rcon_checks")?.evidence ?? [];
const brief = (r: RunResult) => ({
  runId: r.report.runId, overall: r.summary.overall, describe: describeSummary(r.summary), bootMs: r.report.bootMs, doneReportedSec: r.report.doneReportedSec, peakRssMb: r.report.peakRssKb ? Math.round(r.report.peakRssKb / 1024) : null,
  checks: Object.fromEntries(r.report.checks.map((c) => [c.id, c.status])), rcon: rconEv(r), log: r.report.checks.find((c) => c.id === "startup_log_clean")?.evidence.slice(0, 8), plugins: r.report.checks.find((c) => c.id === "plugins_enabled")?.evidence.slice(0, 6),
  engine: r.report.engine, artifacts: r.report.artifacts, collected: (r.report.collected ?? []).map((c) => ({ path: c.path, kind: c.kind, bytes: c.bytes, sha256: c.sha256, entries: c.entries, error: c.error })), notes: r.report.notes,
});

/** Prepare: verified BetterModel jar + library seeds, allowlisted API jars, the TfCreature fixture jar. */
function prepare() {
  const out: Record<string, unknown> = {};
  out.fetchBetterModel = execFileSync(process.execPath, [path.join(ROOT, "services/modbuilder/tools/bettermodel/fetch-bettermodel.js"), ROOT, TF], { encoding: "utf8" }).trim();
  out.fetchDeps = execFileSync(process.execPath, [path.join(ROOT, "services/modbuilder/tools/fetch-import-deps.js"), path.join(ROOT, "lib/cyrus/import/deps.json"), `${T}/cyrus-import-deps`], { encoding: "utf8" }).trim().split("\n").filter((l) => /bettermodel|verified|ok/i.test(l));
  mkdirSync(WORK, { recursive: true });
  const cp = `${WORK}/cp-26.2-bettermodel.txt`;
  writeFileSync(cp, readFileSync(`${T}/r0-26x/classpath/26.2.txt`, "utf8").trim() + `:${T}/cyrus-import-deps/bettermodel-api-3.5.0.jar:${T}/cyrus-import-deps/bettermodel-bukkit-api-3.5.0.jar`);
  const jar = `${TF}/inbox/fx-r6/TfCreature-1.0.2.jar`;
  rmSync(jar, { force: true });
  out.fixtureBuild = execFileSync("bash", [path.join(ROOT, "services/modbuilder/tools/testflight/fixtures/build.sh"), path.join(ROOT, "services/modbuilder/tools/testflight/fixtures/creature"), "1.21.4", `${TF}/jdk/25`, "25", cp, jar], { encoding: "utf8" }).trim();
  return out;
}

const BM_JAR = `${TF}/bettermodel/bettermodel-3.5.0-paper.jar`;
const FIX_JAR = `${TF}/inbox/fx-r6/TfCreature-1.0.2.jar`;
const LOADER_JAR = `${TF}/inbox/fx/NxeonPackLoader-0.1.0.jar`;
const SEEDS = [{ from: "bettermodel-3.5.0-paper-libraries", to: "libraries" }, { from: "bettermodel-3.5.0-libby", to: "plugins/BetterModel/.libs" }];
const IGNORE_OFFLINE = [
  { id: "bm-no-net-version", pattern: "\\[BetterModel\\] (Unable to get BetterModel's version info|Reason: |If you want to see the stack trace)" },
];

/** Compile the golden RigSpecs through the production portal check, deliver them onto a staging guest, seed it. */
async function stageModels(seedName: string, extra: { name: string; data: string }[] = []) {
  const specs = ["banshee", "ghoul", "dire_wolf"].map((n) => ({ name: n, spec: JSON.parse(readFileSync(path.join(ROOT, `test/fixtures/cyrus-creatures/${n}.json`), "utf8")) }));
  const chk = checkReturnedCreatures(specs, NS);
  if (chk.dropped.length) throw new Error(`fixtures dropped: ${JSON.stringify(chk.dropped)}`);
  const stage = `${WORK}/guest-${seedName}`;
  rmSync(stage, { recursive: true, force: true });
  const gfs = new LocalGuestFs(stage);
  const rows = new Map<string, unknown>();
  const r = await deliverCreatures({ serverId: "flight", mcVersion: "26.2", namespace: NS, projectId: "flight", creatures: chk.ok.map((c) => ({ name: c.name, key: c.key, spec: c.input, bbmodelSha256: c.compiled.bbmodelSha256 })) }, {
    managed: { db: fakeDb(rows), installer: memoryInstaller(), catalog: loadCatalog() }, fs: gfs, env: { CYRUS_MANAGED_PLUGINS_REAL: "1", CYRUS_CREATURES: "1" },
  });
  if (!r.ok) throw new Error(`deliverCreatures: ${r.error}`);
  const models = `${stage}/opt/mc/plugins/BetterModel/models`;
  for (const e of extra) writeFileSync(`${models}/${e.name}`, e.data);
  const seedDir = `${TF}/seeds/${seedName}`;
  rmSync(seedDir, { recursive: true, force: true });
  cpSync(models, seedDir, { recursive: true });
  return { delivered: r, config: readFileSync(`${stage}/opt/mc/plugins/BetterModel/config.yml`, "utf8"), creatures: chk.ok.map((c) => ({ name: c.name, key: c.key, bbmodelSha256: c.compiled.bbmodelSha256, bytes: c.compiled.stats.bytes, skin: c.compiled.layout.size, quality: c.quality.verdict })), seedName };
}

const baseSpec = (plugins: string[], seeds: { from: string; to: string }[], files: { path: string; content: string }[], rcon: TestFlightSpec["rcon"], collect: string[] = []): TestFlightSpec => ({
  version: "26.2", plugins: plugins.map((p) => ({ remotePath: p })), seeds, files, rcon, collect, logIgnore: IGNORE_OFFLINE, timeouts: { bootSec: 240, totalSec: 600 },
});

async function flightLoad(out: Record<string, unknown>) {
  const st = await stageModels("r6-models-load");
  const K = (n: string) => `${NS}_${n}`;
  const spec = baseSpec([BM_JAR, FIX_JAR], [...SEEDS, { from: st.seedName, to: "plugins/BetterModel/models" }], [{ path: "plugins/BetterModel/config.yml", content: st.config }], [
    { id: "difficulty", command: "difficulty easy" },
    { id: "models", command: `tfcreature models ${K("banshee")}`, expect: ["models=3", "has=true", K("ghoul"), K("dire_wolf")] },
    { id: "spawn-banshee", command: `tfcreature spawn ${K("banshee")} 1`, expect: ["spawned=1", "idle=1", "silent=true", "invisible=true", "zombies=1"] },
    { id: "stats-1", command: "tfcreature stats", waitMs: 1500, expect: ["mobsAlive=1", "trackersOpen=1"] },
    { id: "attack", command: `tfcreature attack ${NS}:banshee.attack`, expect: ["attack_started=1 of=1"] },
    { id: "hurt", command: `tfcreature hurt ${NS}:banshee.hurt`, expect: ["hurt_started=1 of=1"] },
    { id: "stats-2", command: "tfcreature stats", waitMs: 1500, expect: ["mobsAlive=1"] },
    { id: "death", command: `tfcreature death ${NS}:banshee.death`, expect: ["death_started=1 of=1"] },
    { id: "despawn", command: "tfcreature despawn", waitMs: 500, expect: ["closed=1", "removed=1", "zombies=0"] },
    { id: "spawn-ghoul", command: `tfcreature spawn ${K("ghoul")} 1`, expect: ["spawned=1", "idle=1"] },
    { id: "spawn-wolf", command: `tfcreature spawn ${K("dire_wolf")} 1`, expect: ["spawned=1", "idle=1"] },
    { id: "attack-2", command: "tfcreature attack", expect: ["attack_started=2 of=2"] },
    { id: "despawn-2", command: "tfcreature despawn", waitMs: 500, expect: ["closed=2", "removed=2", "zombies=0"] },
    { id: "stats-end", command: "tfcreature stats", waitMs: 500, expect: ["zombies=0", "trackersOpen=0", "mobsAlive=0"] },
    { id: "bm-reload", command: "bettermodel reload", waitMs: 3000, required: false },
    { id: "models-after-reload", command: `tfcreature models ${K("banshee")}`, waitMs: 2000, expect: ["models=3", "has=true"] },
  ], ["console.log", "plugins/BetterModel/", "plugins/BetterModel/build.zip"]);
  const r = await fly(spec, "load");
  const files = await pullCollected(r.report, { remote: localRemote });
  out.load = { stage: { creatures: st.creatures, delivered: st.delivered }, flight: brief(r) };
  const log = files.get("console.log")?.toString("utf8") ?? "";
  (out.load as Record<string, unknown>).betterModelLog = log.split("\n").filter((l) => /BetterModel|TfCreature/.test(l)).filter((l) => !/Relocations applied/.test(l)).slice(0, 60);
  const zip = files.get("plugins/BetterModel/build.zip");
  if (!zip) throw new Error("no build.zip collected");
  writeFileSync(`${WORK}/build.zip`, zip);
  const n = normalizeBetterModelPack(zip);
  (out.load as Record<string, unknown>).pack = n.ok ? { rawBytes: zip.length, rawSha256: sha(zip), normalizedBytes: n.bytes, normalizedSha256: sha(n.zip), entries: n.entries, contentSha256: n.contentSha256 } : { error: n.error };
  return { zip, st };
}

async function flightPackLoader(out: Record<string, unknown>, zip: Buffer, st: Awaited<ReturnType<typeof stageModels>>) {
  // the hand-off exactly as production does it: build.zip on the "server" -> normalised -> published -> packs.json
  const guest = `${WORK}/guest-handoff`;
  rmSync(guest, { recursive: true, force: true });
  const gfs = new LocalGuestFs(guest);
  await gfs.writeFile("/opt/mc/plugins/BetterModel/build.zip", zip);
  const store = new LocalDiskStore(`${WORK}/packstore`, "https://packs.example.invalid");
  const h = await handoffBetterModelPack({ fs: gfs, store });
  const h2 = await handoffBetterModelPack({ fs: gfs, store });
  const cfg = await readLoaderConfig(gfs);
  if (!h.ok || !cfg.ok || !cfg.config) throw new Error(`hand-off failed: ${JSON.stringify(h)}`);
  const packsJson = serializeLoaderConfig(cfg.config);
  const sha1 = cfg.config.packs[0].sha1;
  const spec = baseSpec([LOADER_JAR, BM_JAR, FIX_JAR], [...SEEDS, { from: st.seedName, to: "plugins/BetterModel/models" }], [{ path: "plugins/BetterModel/config.yml", content: st.config }, { path: LOADER_CONFIG_PATH, content: packsJson }], [
    { id: "nxpacks-list", command: "nxpacks list", expect: [sha1, "1 pack"] },
    { id: "nxpacks-status", command: "nxpacks status", expect: ["config=ok"] },
    { id: "models", command: `tfcreature models ${NS}_banshee`, expect: ["has=true"] },
    { id: "plugins", command: "plugins", expect: ["BetterModel", "NxeonPackLoader", "TfCreature"] },
  ], ["plugins/BetterModel/build.zip"]);
  const r = await fly(spec, "packloader");
  const files = await pullCollected(r.report, { remote: localRemote });
  const again = files.get("plugins/BetterModel/build.zip");
  const n2 = again ? normalizeBetterModelPack(again) : null;
  out.packloader = { handoff: h, handoffAgain: h2, packsJson: JSON.parse(packsJson), flight: brief(r), secondBootPack: n2 && n2.ok ? { rawSha256: sha(again!), normalizedSha256: sha(n2.zip), sameNormalizedAsFirstBoot: n2.ok && h.ok && createHash("sha1").update(n2.zip).digest("hex") === h.sha1 } : null };
}

async function flightMalformed(out: Record<string, unknown>) {
  const st = await stageModels("r6-models-bad", [
    { name: `${NS}_broken_json.bbmodel`, data: '{"meta":{"format_version":"5.0"},"elements":[' },
    { name: `${NS}_bad_shape.bbmodel`, data: JSON.stringify({ meta: { format_version: "5.0", model_format: "free" }, resolution: { width: 16, height: 16 }, elements: "nope", outliner: 7, textures: [], animations: {} }) },
    { name: `${NS}_empty.bbmodel`, data: "" },
  ]);
  const spec = baseSpec([BM_JAR, FIX_JAR], [...SEEDS, { from: st.seedName, to: "plugins/BetterModel/models" }], [{ path: "plugins/BetterModel/config.yml", content: st.config }], [
    { id: "difficulty", command: "difficulty easy" },
    { id: "models", command: `tfcreature models ${NS}_banshee`, expect: ["has=true", `${NS}_ghoul`], expectNot: ["broken_json", "bad_shape", `${NS}_empty`] },
    { id: "spawn", command: `tfcreature spawn ${NS}_banshee 1`, expect: ["spawned=1", "idle=1"] },
    { id: "despawn", command: "tfcreature despawn", expect: ["removed=1"] },
    { id: "plugins", command: "plugins", expect: ["BetterModel", "TfCreature"] },
  ], ["console.log"]);
  // the bad models are EXPECTED to log load errors: keep the default matchers, report every hit as evidence
  const r = await fly(spec, "malformed");
  const files = await pullCollected(r.report, { remote: localRemote });
  const log = files.get("console.log")?.toString("utf8") ?? "";
  out.malformed = { flight: brief(r), betterModelLog: log.split("\n").filter((l) => /BetterModel|broken_json|bad_shape|_empty|Exception|ERROR|WARN/.test(l)).filter((l) => !/Relocations applied|OFFLINE|online-mode|authenticate|hackers|Unsafe|yggdrasil|PaperVersion|version information|MacAddress|terminal/.test(l)).slice(0, 40) };
}

async function flightPerf(out: Record<string, unknown>) {
  const st = await stageModels("r6-models-perf");
  const files = [{ path: "plugins/BetterModel/config.yml", content: st.config }];
  const vanilla = await fly({ version: "26.2", timeouts: { bootSec: 240 } }, "perf-vanilla");
  const bmOnly = await fly(baseSpec([BM_JAR, FIX_JAR], [...SEEDS, { from: st.seedName, to: "plugins/BetterModel/models" }], files, [{ id: "stats", command: "tfcreature stats", waitMs: 3000 }]), "perf-bm-only");
  const K = `${NS}_banshee`;
  const steps: TestFlightSpec["rcon"] = [{ id: "difficulty", command: "difficulty easy" }, { id: "stats-0", command: "tfcreature stats", waitMs: 3000 }];
  for (const [n, add] of [[1, 1], [10, 9], [50, 40]] as const) {
    steps.push({ id: `spawn-${n}`, command: `tfcreature spawn ${K} ${add}`, expect: [`spawned=${add}`, `idle=${add}`] });
    steps.push({ id: `stats-${n}`, command: "tfcreature stats", waitMs: 10000, expect: [`trackersOpen=${n}`] });
  }
  steps.push({ id: "attack-50", command: `tfcreature attack ${NS}:banshee.attack`, expect: ["attack_started=50 of=50"] });
  steps.push({ id: "stats-attack", command: "tfcreature stats", waitMs: 5000 });
  steps.push({ id: "despawn", command: "tfcreature despawn", expect: ["closed=50", "removed=50", "zombies=0"] });
  steps.push({ id: "stats-after", command: "tfcreature stats", waitMs: 5000, expect: ["trackersOpen=0", "zombies=0"] });
  const ramp = await fly(baseSpec([BM_JAR, FIX_JAR], [...SEEDS, { from: st.seedName, to: "plugins/BetterModel/models" }], files, steps), "perf-ramp");
  out.perf = { vanilla: brief(vanilla), bettermodelOnly: brief(bmOnly), ramp: brief(ramp) };
}

async function main() {
  const which = process.argv[2] ?? "all";
  const oi = process.argv.indexOf("--out");
  const out: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", realClient: false, aiModel: "none (golden RigSpec fixtures)", bettermodel: "3.5.0 (bettermodel-3.5.0-paper.jar sha256 0f983569...57ed6)", paper: "26.2 build 133", jdk: "Temurin 25.0.4.1+1" };
  out.prepare = prepare();
  if (which === "load" || which === "packloader" || which === "all") {
    const { zip, st } = await flightLoad(out);
    if (which !== "load") await flightPackLoader(out, zip, st);
  }
  if (which === "malformed" || which === "all") await flightMalformed(out);
  if (which === "perf" || which === "all") await flightPerf(out);
  for (const s of ["r6-models-load", "r6-models-bad", "r6-models-perf"]) rmSync(`${TF}/seeds/${s}`, { recursive: true, force: true });
  const text = JSON.stringify(out, null, 1);
  if (oi > 0) writeFileSync(process.argv[oi + 1], text + "\n");
  console.log(text);
}

/** In-memory CyrusServerManagedPlugin (same shape as test/cyrus-creature.test.ts). */
function fakeDb(rows: Map<string, unknown>) {
  type Row = { id: string; serverId: string; key: string; family: string; status: string; version: string | null; sha256: string | null; dependents: string[]; refCount: number };
  const byKey = (s: string, k: string) => rows.get(`${s}/${k}`) as Row | undefined;
  const byId = (id: string) => [...rows.values()].find((r) => (r as Row).id === id) as Row | undefined;
  const table = { update: async ({ where, data }: { where: { id: string }; data: Partial<Row> }) => Object.assign(byId(where.id)!, data), findUnique: async ({ where }: { where: { serverId_key: { serverId: string; key: string } } }) => byKey(where.serverId_key.serverId, where.serverId_key.key) ?? null };
  const tx = {
    $executeRaw: async (_s: TemplateStringsArray, id: string, serverId: string, key: string, family: string) => { if (!byKey(serverId, key)) rows.set(`${serverId}/${key}`, { id, serverId, key, family, status: "removed", version: null, sha256: null, dependents: [], refCount: 0 }); return 1; },
    $queryRaw: async (_s: TemplateStringsArray, serverId: string, key: string) => { const r = byKey(serverId, key); return r ? [{ ...r }] : []; },
    cyrusServerManagedPlugin: table,
  };
  return { $transaction: async (fn: (t: typeof tx) => unknown) => fn(tx), cyrusServerManagedPlugin: table } as never;
}

void managedConfigTemplate; void existsSync;
main().catch((e) => { console.error(e); process.exit(1); });

