// REAL Test Flights of the Cyrus R3 creature pipeline ON node-2 (not part of the unit suite: boots real Paper 26.2).
//   scripts/devhost run -- npx tsx test/cyrus-creature-real.ts [load|packloader|malformed|perf|all] [--out results.json]
// SERVER SIDE ONLY: no Minecraft client connects, so how the creatures LOOK and ANIMATE for a player, the resource
// pack download and the accept prompt are NOT verified. No AI model is used (the RigSpecs are the golden fixtures).
// What runs: the PRODUCTION code paths (portal re-check + compile = lib/cyrus/creature/portal.ts, the server delivery
// = deliverCreatures with the Nxeon-managed config, onto a staging dir that becomes the flight's
// plugins/BetterModel/models seed, the pack hand-off = handoffBetterModelPack) around a real server with the pinned
// BetterModel 3.5.0 jar and the TfCreature fixture (services/modbuilder/tools/testflight/fixtures/creature, compiled
// with javac --release 25 against the real 26.2 classpath + the allowlisted BetterModel API jars).
// Flights run one at a time (Test Flight lock; "busy" -> retry with backoff).
import { createHash } from "node:crypto";
import { execFileSync, spawn } from "node:child_process";
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
