  mkdirSync(WORK, { recursive: true });
  const cp = `${WORK}/cp-26.2-bettermodel.txt`;
  writeFileSync(cp, readFileSync(`${T}/r0-26x/classpath/26.2.txt`, "utf8").trim() + `:${T}/cyrus-import-deps/bettermodel-api-3.5.0.jar:${T}/cyrus-import-deps/bettermodel-bukkit-api-3.5.0.jar`);
