    const { getVersion } = await import("../lib/cyrus/versions/registry.ts");
    const row = getVersion("26.2")!; const was = row.buildable;
    const deps = { ...assetRequestDeps, creaturesEnabled: () => true };
    try {
      row.buildable = true;
      const want: Record<string, boolean> = { free: false, katara: false, saka: false, all: true, comp: true };
      for (const [who, ok] of Object.entries(want)) {
        const root = `mb${uniq}${who}`.slice(0, 40);
        const r = await resolveBuildAssets({ userId: uid(who), rootBuildId: root, change: false, explicit: ["creature"], text: "A banshee", mcVersion: "26.2" }, deps);
        assert.equal(r.service?.creature === true, ok, `${who}: ${JSON.stringify(r.meta)}`);
        if (ok) assert.match(r.service!.namespace, /^nx_[a-z0-9]{8}$/);
      }
    } finally { row.buildable = was; }
    const old = await resolveBuildAssets({ userId: uid("all"), rootBuildId: `mb${uniq}old`, change: false, explicit: ["creature"], text: "A banshee", mcVersion: "1.21.11" }, deps);
    assert.equal(old.service?.creature, undefined);
    assert.equal(old.service?.sound, true, "the banshee still gets its sounds on 1.21.11");
    assert.ok(old.meta!.notices.some((n) => /need Minecraft 26\.x/.test(n)));
  });

  it("sync: one revision + one model asset; re-sync and concurrent first syncs never duplicate", async () => {
    const { createProject } = await import("../lib/cyrus/engine-core/store.ts");
    const { syncBuildAssets } = await import("../lib/cyrus/assets/sync.ts");
    const { defaultAssetSyncDeps } = await import("../lib/cyrus/assets/sync-deps.ts");
    const root = `mb${uniq}csync`;
    const p = await createProject({ userId: uid("all"), game: "minecraft", rootBuildId: root });
    const spec = banshee(); spec.sounds = { hurt: `${p.namespace}:banshee.hurt` };
    const bad = banshee(); bad.name = "broken"; bad.template.features = ["wings"];
    const ar = { namespace: p.namespace, promptVersion: "mb-assets-2026-10-10.3", qualityVersion: "tq-1", kept: false, downgraded: [], warnings: [], textures: [], creatures: [{ name: "banshee", path: "assets/creatures/banshee.json", sha256: "", spec }, { name: "broken", path: "assets/creatures/broken.json", sha256: "", spec: bad }] };
    const build = { id: root, userId: uid("all"), rootBuildId: root, mcVersion: "26.2", pluginName: "Banshee", jarName: "Banshee-1.0.0.jar", jarSha256: "c".repeat(64) };
    const deps = defaultAssetSyncDeps(env);
    const a = (await syncBuildAssets(build, ar, deps))!;
    assert.equal(a.status, "none", "creatures need no Nxeon pack (BetterModel builds its own)");
    assert.deepEqual(a.creatures!.map((c) => c.key), [`${p.namespace}_banshee`]);
    assert.deepEqual(a.dropped.map((d) => [d.name, d.kind]), [["broken", "creature"]]);
    assert.ok(a.notices.some((n) => /Nxeon-managed BetterModel/.test(n)));
    const again = await Promise.all([syncBuildAssets(build, ar, deps), syncBuildAssets(build, ar, deps), syncBuildAssets(build, ar, deps)]);
    for (const x of again) assert.equal(x!.revisionId, a.revisionId);
    const revs = await db.cyrusRevision.findMany({ where: { projectId: p.id } });
    assert.equal(revs.length, 1);
    const paths = (revs[0].manifest as { path: string; role: string }[]).map((m) => `${m.role}:${m.path}`).sort();
    assert.deepEqual(paths, ["artifact:plugin/Banshee-1.0.0.jar", `asset:assets/creatures/banshee.json`, `asset:bettermodel/${p.namespace}_banshee.bbmodel`]);
    const assets = await db.cyrusProjectAsset.findMany({ where: { projectId: p.id } });
    assert.equal(assets.length, 1);
    assert.equal(assets[0].kind, "model");
    assert.equal(assets[0].mime, "application/vnd.nxeon.rig-spec+json");
    const prov = assets[0].provenance as { compiler: string; bbmodelSha256: string; quality: { verdict: string } };
    assert.equal(prov.compiler, "rig-c1"); assert.equal(prov.bbmodelSha256, a.creatures![0].bbmodelSha256); assert.equal(prov.quality.verdict, "pass");

    const root2 = `mb${uniq}crace`;
    const p2 = await createProject({ userId: uid("all"), game: "minecraft", rootBuildId: root2 });
    const ar2 = { ...ar, namespace: p2.namespace, creatures: [{ ...ar.creatures[0], spec: { ...spec, sounds: {} } }] };
    const b2 = { ...build, id: root2, rootBuildId: root2 };
    const race = await Promise.all([syncBuildAssets(b2, ar2, deps), syncBuildAssets(b2, ar2, deps), syncBuildAssets(b2, ar2, deps)]);
    assert.equal(new Set(race.map((x) => x!.revisionId)).size, 1);
    assert.equal(await db.cyrusRevision.count({ where: { projectId: p2.id } }), 1);
    assert.equal(await db.cyrusProjectAsset.count({ where: { projectId: p2.id } }), 1);
  });

  it("delivery with the real managed service: BetterModel ensured (ref-counted), model written, released on removal", async () => {
    const { deliverCreatures, removeCreatures } = await import("../lib/cyrus/creature/deliver.ts");
    const { loadCatalog } = await import("../lib/cyrus/managed/catalog.ts");
    const { memoryInstaller } = await import("../lib/cyrus/managed/installer.ts");
    const { LocalGuestFs } = await import("../lib/mods/guest-fs.ts");
    const { checkReturnedCreatures } = await import("../lib/cyrus/creature/portal.ts");
    const ns = "nx_dbcr34tr";
    const c = checkReturnedCreatures([{ name: "banshee", spec: banshee() }], ns).ok[0];
    const gfs = new LocalGuestFs(path.join(tmp, "guest"));
    const deps = { managed: { db, installer: memoryInstaller(), catalog: loadCatalog() }, fs: gfs, env: { CYRUS_MANAGED_PLUGINS_REAL: "1", CYRUS_CREATURES: "1" } };
    const serverId = uid("srv");
    const stored = [{ name: c.name, key: c.key, spec: c.input, bbmodelSha256: c.compiled.bbmodelSha256 }];
    const a = await deliverCreatures({ serverId, mcVersion: "26.2", namespace: ns, projectId: "pA", creatures: stored }, deps);
    assert.ok(a.ok && a.bettermodel === "installed", JSON.stringify(a));
    const b = await deliverCreatures({ serverId, mcVersion: "26.2", namespace: "nx_dbcr34ts", projectId: "pB", creatures: checkReturnedCreatures([{ name: "banshee", spec: banshee() }], "nx_dbcr34ts").ok.map((x) => ({ name: x.name, key: x.key, spec: x.input, bbmodelSha256: x.compiled.bbmodelSha256 })) }, deps);
    assert.ok(b.ok && b.bettermodel === "ref_added", JSON.stringify(b));
    let row = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId, key: "bettermodel" } } });
    assert.equal(row!.refCount, 2); assert.equal(row!.version, "3.5.0"); assert.equal(row!.family, "26");
    const r1 = await removeCreatures({ serverId, mcVersion: "26.2", namespace: ns, projectId: "pA" }, deps);
    assert.ok(r1.ok && r1.bettermodel === "ref_dropped");
    assert.ok(fs.existsSync(path.join(tmp, "guest/opt/mc/plugins/BetterModel/models/nx_dbcr34ts_banshee.bbmodel")), "the other project's model is untouched");
    const r2 = await removeCreatures({ serverId, mcVersion: "26.2", namespace: "nx_dbcr34ts", projectId: "pB" }, deps);
    assert.ok(r2.ok && r2.bettermodel === "removed");
    row = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId, key: "bettermodel" } } });
    assert.equal(row!.refCount, 0); assert.equal(row!.status, "removed");
  });
});

