// a test allowlist whose jars exist here (the real deps.json pins the real jars' hashes)
const depsDir = path.join(dir, "deps");
fs.mkdirSync(depsDir);
const real = JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/import/deps.json"), "utf8"));
for (const d of real.dependencies) {
  if (d.id === "protocollib") continue; // "allowlisted but not installed" case
  const bytes = Buffer.from(`fake jar ${d.id}`);
  fs.writeFileSync(path.join(depsDir, d.file), bytes);
  d.sha256 = crypto.createHash("sha256").update(bytes).digest("hex");
}
fs.writeFileSync(path.join(dir, "deps.json"), JSON.stringify(real));
for (const f of ["claude.log", "javac.log"]) fs.writeFileSync(path.join(dir, f), "");
